const e={ramir:{name:"Рамир",identification:"в красном",cue:"Из стойки уходи вперёд",priority:"Проверить выход из низкой стойки: не вставать отдельно перед разгоном."},misha:{name:"Миша",identification:"с белыми волосами",cue:"Толкни дорожку назад — унеси тело вперёд",priority:"Проверить вторую постановку стопы и продолжение разгона."}},n=JSON.parse('[{"id":"back","category":"back","title":"Спина: наклон и форма — разные проверки","cue":"Отдельную команду про спину сейчас не добавляем","target":"back-axis.svg","targetCaption":"Условная схема различия измерений. Не ваш позвоночник и не норматив.","sources":[["Форма позвоночника при беге, 2015","https://pubmed.ncbi.nlm.nih.gov/25770754/"],["Раздельная оценка поясницы, 2025","https://pubmed.ncbi.nlm.nih.gov/40288298/"]],"people":{"ramir":{"good":"У стены большого складывания в тазу не видно. Общую линию сильнее выпрямлять сейчас не нужно.","change":"Наклон туловища измерен. Точный прогиб поясницы по этим кадрам оценить нельзя.","why":"Линия плечо–таз показывает ориентацию туловища, но не форму позвоночника между точками. Контур футболки не заменяет анатомические ориентиры.","how":"В Wall пусть двигается нога, а грудь и пояс не помогают качанием. В готовности 3-point сгибание в тазу допустимо; прямой Wall-линии там не требуем.","check":"Снять Hold и три медленных подъёма каждой ногой строго сбоку в облегающей спортивной одежде.","photos":[{"file":"mobile/red-wall.png","caption":"Wall Hold: общая линия Рамира","full":"annotations/red-wall.png"}],"limits":"Камера низко и косо. Не подтверждены ни выраженный прогиб, ни его точное отсутствие.","angles":[["Плечо–таз к горизонтали кадра","≈56°"],["К вертикали кадра","≈34°"],["Плечо–таз–опорный голеностоп","≈177°"]]},"misha":{"good":"У стены большого складывания в тазу не видно. Общую линию сильнее выпрямлять сейчас не нужно.","change":"Наклон туловища измерен. Точный прогиб поясницы по этим кадрам оценить нельзя.","why":"Наклон плечо–таз и локальная кривизна спины — разные величины. Позвоночник не обязан быть палкой без естественных изгибов.","how":"В Wall двигается нога при устойчивой груди и поясе. В готовности 3-point тазобедренные суставы согнуты — это допустимо.","check":"Снять Hold и три медленных подъёма каждой ногой строго сбоку в облегающей спортивной одежде.","photos":[{"file":"mobile/white-wall.png","caption":"Wall Hold: общая линия Миши","full":"annotations/white-wall.png"}],"limits":"Разницу нескольких градусов с Рамиром не считаем преимуществом. Точного поясничного угла нет.","angles":[["Плечо–таз к горизонтали кадра","≈52°"],["К вертикали кадра","≈38°"],["Плечо–таз–опорный голеностоп","≈171°"]]}}},{"id":"wall-hold","category":"wall","title":"Wall Hold: колено вперёд, меньше сжатия","cue":"Колено вперёд, не к животу","target":"wall-target.svg","targetCaption":"Условная схема выбранной Wall-модели. Обязательных углов не задаёт.","sources":[["Модель Landow","https://coachathletics.com.au/coaching-education/three-great-acceleration-drills-loren-landows-drill-progression"],["Демонстрация Landow","https://www.youtube.com/watch?v=uwDEyE6phDc&t=76s"]],"people":{"ramir":{"good":"Наклон подходит для выбранной задачи: плечо, таз и опорный голеностоп примерно на одной линии.","change":"Попробуй поднятую ногу меньше приближать к животу. Сейчас она сжата сильнее выбранной модели Landow.","why":"Дополнительное подтягивание колена не является целью. Проверяем, удобнее ли из менее сжатой позы напрямую сменить ноги без перестановки корпуса.","how":"Упрись в стену. Поднимай колено вперёд и останови подъём немного раньше. Ощущение: нога движется отдельно, пояс остаётся на месте.","check":"Удержать на обеих сторонах, затем проверить March и одну смену. Не переходить к переступанию почти прямыми ногами.","photos":[{"file":"mobile/red-wall.png","caption":"Wall Hold Рамира: поднятая нога","full":"annotations/red-wall.png"}],"limits":"Это проба под конкретную тренерскую модель. Улучшение времени старта от неё не доказано.","angles":[["Поднятое колено","≈54°"],["Туловище–поднятое бедро","≈49°"]]},"misha":{"good":"Большого излома общей линии у стены нет. Специально наклоняться сильнее сейчас не нужно.","change":"Попробуй меньше сжимать поднятую ногу к животу.","why":"Проверяем управление ногой и прямую смену, а не максимальную высоту колена. Меньшая амплитуда полезна лишь если улучшает задачу.","how":"Подними колено вперёд, остановись раньше, не догоняй его грудью. Ощущение: нога поднялась, пояс остался на месте.","check":"Устойчивый Hold на обеих сторонах, затем одинаковые March и быстрая одиночная смена.","photos":[{"file":"mobile/white-wall.png","caption":"Wall Hold Миши: поднятая нога","full":"annotations/white-wall.png"}],"limits":"Углы — проекции. Ровно 90° каждому суставу не назначаем.","angles":[["Поднятое колено","≈58°"],["Туловище–поднятое бедро","≈58°"]]}}},{"id":"wall-march","category":"wall","title":"Wall March: три повторяемых подъёма","cue":"Колено вперёд, не к животу","target":"march-target.svg","targetCaption":"Условная последовательность: поднять, удержать, вернуть.","sources":[["Wall March: авторская демонстрация","https://www.youtube.com/watch?v=G1WvfCbg8uE"]],"people":{"ramir":{"good":"Возвращение на две стопы между медленными подъёмами допустимо.","change":"Используй менее сжатую верхнюю позу из Hold; не ускоряй марш ради количества.","why":"Цель — одинаковое движение ногой при устойчивом туловище. Быстрая смена проверяется отдельно в Switch.","how":"Поднять, удержать 1–2 секунды, вернуть. Ощущение: двигается нога, грудь и пояс почти неподвижны.","check":"Три похожих подъёма каждой ногой. При нарастающем качании уменьшить подъём или закончить подход.","photos":[{"file":"red-wall-two-feet.jpg","caption":"Рамир: промежуточное положение на двух стопах","full":null},{"file":"red-wall-motion.gif","caption":"Рамир: выбранное движение у стены","full":null}],"limits":"Анимация идёт по времени файла. Реальная частота при неизвестном замедлении не измерена; голова частично обрезана.","angles":[]},"misha":{"good":"Возвращение на две стопы для спокойного обучения допустимо.","change":"Повторяй одну верхнюю позу без помощи всем телом.","why":"Так учимся отдельно управлять ногой. Даже быстрый марш через остановку не заменяет прямой Single Switch.","how":"Поднять ногу, удержать 1–2 секунды, вернуть. Не стараться прижать колено к животу.","check":"Три похожих подъёма каждой ногой без нарастающего движения туловища.","photos":[{"file":"white-wall-two-feet.jpg","caption":"Миша: промежуточное положение на двух стопах","full":null},{"file":"white-wall-motion.gif","caption":"Миша: выбранное движение у стены","full":null}],"limits":"Реальную скорость анимация не подтверждает. Хороший March сам по себе не доказывает ускорение 10 м.","angles":[]}}},{"id":"wall-switch","category":"wall","title":"Single Switch: одна смена — фиксация","cue":"Сменил — замри","target":"switch-target.svg","targetCaption":"Условная схема одной быстрой смены и устойчивого окончания.","sources":[["Прогрессия Landow","https://www.youtube.com/watch?v=uwDEyE6phDc&t=76s"]],"people":{"ramir":{"good":"Исходную позу можно спокойно собрать перед повтором.","change":"В просмотренной серии между верхними положениями есть отдельная остановка на двух стопах. Для Single Switch это не выполняет задачу.","why":"Сейчас получаются два подъёма подряд. Нужна быстрая смена ролей ног с устойчивой новой опорой.","how":"Начни с одной ногой наверху. Одним коротким действием поменяй ноги и замри. Между повторами подготовься заново.","check":"Новый Hold без отдельного маршевого подъёма и заметного провала таза. Если не получается — меньше смен и снова March.","photos":[{"file":"red-wall-two-feet.jpg","caption":"Рамир: остановка на двух стопах","full":null}],"limits":"Оценена выбранная серия, не вся папка. Не требуем физически нулевого времени двойной опоры.","angles":[]},"misha":{"good":"Исходную позу можно спокойно собрать перед повтором.","change":"В просмотренной серии между верхними положениями есть отдельная остановка на двух стопах. Для Single Switch это не выполняет задачу.","why":"Сейчас получаются два подъёма подряд. Нужна быстрая смена ролей ног с устойчивой новой опорой.","how":"Начни с одной ногой наверху. Одним коротким действием поменяй ноги и замри. Между повторами подготовься заново.","check":"Новый Hold без отдельного маршевого подъёма и заметного провала таза. Если не получается — меньше смен и снова March.","photos":[{"file":"white-wall-two-feet.jpg","caption":"Миша: остановка на двух стопах","full":null}],"limits":"Оценена выбранная серия, не вся папка. Не требуем физически нулевого времени двойной опоры.","angles":[]}}},{"id":"falling","category":"falling","title":"Falling: наклон всем телом и выход вперёд","cue":"Падай целиком и уходи вперёд","target":"falling-target.svg","targetCaption":"Условная схема направления. Не требование заблокировать колени.","sources":[["Falling: демонстрация","https://www.youtube.com/watch?v=Rd3Bl2yAydY"],["Переходы в ускорении","https://doi.org/10.1242/bio.20148284"]],"people":{"ramir":{"good":"Резкого вставания в первые три опоры нет. Первый шаг не выглядит намеренно вытянутым; большого складывания в тазу не видно.","change":"Если задача именно Falling, попробуй меньше отдельного подседания до выхода.","why":"Так упражнение яснее учит переходу от наклона вперёд к бегу и меньше смешивается со стартом из приседа.","how":"Из спокойной вертикальной стойки позволь всему телу наклониться от опоры. Когда нужен шаг — уходи в бег. Колени не зажимай.","check":"Продвижение вперёд на первых трёх опорах без отдельного приседания. Не удерживать одну цифру наклона.","photos":[{"file":"mobile/red-contact-1.png","caption":"Рамир: первая новая опора Falling","full":"annotations/red-contact-1.png"}],"limits":"Интенсивность и реальное время неизвестны. Небольшое естественное сгибание коленей допустимо.","angles":[["Наклон туловища: опоры 1 / 2 / 3","≈58° / 50° / 60°"]]},"misha":{"good":"По просмотренной демонстрации с жестами нельзя оценить качество твоего Falling-разгона.","change":"Нужна ясно обозначенная попытка ускорения до 10 м.","why":"Объяснение шагами и настоящий разгон — разные задачи. Поэтому ошибку наклона сейчас не назначаем.","how":"Используй две Falling-попытки из плана: наклон всем телом от стоп, затем переход в бег.","check":"Снять первые пять опор сбоку, обозначить намерение ускоряться.","photos":[],"limits":"Собственного подтверждённого Falling-кадра для технической оценки пока нет. Схема не заменяет его.","angles":[]}}},{"id":"red-start","category":"start","title":"3-point Рамира: уйти вперёд из низкой стойки","cue":"Из стойки уходи вперёд","target":"forward-target.svg","targetCaption":"Условная схема продвижения; место постановки стопы не назначено.","sources":[["Демонстрация 3-point","https://www.youtube.com/watch?v=dgewJyq8ZFc"],["Обзор биомеханики старта","https://doi.org/10.1007/s40279-019-01138-1"]],"people":{"ramir":{"good":"Falling показывает другой твой выход: там нет такого резкого выпрямления на первых трёх опорах.","change":"В выбранной низкой попытке туловище становится почти вертикальным уже ко второй–третьей опоре. Если это был разгон, проверяем это в первую очередь.","why":"Если сначала встаёшь с корточек, а потом начинаешь бежать, низкая поза не помогает сразу продвинуть тело вперёд. По углам потерю времени не доказать.","how":"До старта немного подними таз из глубокой стойки и почувствуй обе стопы. Грудь и пояс уходят вперёд вместе, без отдельного вставания.","check":"Два назначенных 3-point до 10 м: без новой команды и с ней. Первые пять опор сбоку. Больше наклона ценой скованности не считается улучшением.","photos":[{"file":"mobile/red-low-contact-2.png","caption":"Рамир: вторая опора низкого старта","full":"annotations/red-low-contact-2.png"},{"file":"mobile/red-contact-2.png","caption":"Рамир: вторая опора Falling — другой собственный выход","full":"annotations/red-contact-2.png"}],"limits":"Усилие и намерение низкой попытки неизвестны. Если показывал два шага, запись не доказывает ошибку максимального старта.","angles":[["Низкая попытка: опоры 1 / 2 / 3","≈63° / 79° / 87°"]]}}},{"id":"white-start","category":"start","title":"3-point Миши: проверить вторую стопу","cue":"Толкни дорожку назад — унеси тело вперёд","target":"forward-target.svg","targetCaption":"Условная схема направления действия, не обязательной длины шага.","sources":[["3-point и первые 30 м","https://www.youtube.com/watch?v=AYLad378i30"],["Переходы в ускорении","https://doi.org/10.1242/bio.20148284"]],"people":{"misha":{"good":"Готовность пригодна: таз выше плеч, одна рука на дорожке. Начало движения направлено вперёд; садиться глубже не нужно.","change":"На второй опоре стопа впереди колена по направлению бега. К четвёртой опоре туловище почти вертикально.","why":"Если достаёшь длинный шаг стопой, контакт может мешать продвижению. Само положение стопы ещё не доказывает торможение: центр массы и силы не измерены.","how":"Думай о продвижении тела за счёт опоры. Следующая нога подхватывает движение, а не ищет далёкую отметку. Не задерживай ногу на земле ради полного разгибания.","check":"Два сопоставимых 3-point на 10 м сбоку. Проверить подход второй стопы, затем опоры 3–5. Только более короткие шаги или более низкая голова — не улучшение.","photos":[{"file":"mobile/white-contact-2.png","caption":"Миша: вторая область опоры, движение влево","full":"annotations/white-contact-2.png"}],"limits":"Голень отклонена назад по ходу движения. Первый контакт частично закрыт; точная длина шагов неизвестна.","angles":[["Туловище на второй опоре","≈44°"],["Голень к горизонтали кадра","≈70°"],["Туловище на опорах 4–5","≈81–82°"]]}}},{"id":"push-up","category":"pushup","title":"Push-Up: проверить пользу, не только низкую позу","cue":null,"target":"forward-target.svg","targetCaption":"Условная схема цели: выход и продолжение движения вперёд.","sources":[["Push-Up: демонстрация","https://www.youtube.com/watch?v=Wgrmhx6EIE4"],["3-point: демонстрация","https://www.youtube.com/watch?v=dgewJyq8ZFc"]],"people":{"ramir":{"good":"Сбор ног под тело при выходе с пола допустим. Прямую Wall-линию на всех стадиях Push-Up не требуем.","change":"Часть первых контактов закрывают другие люди. Преимущество для твоего обычного старта не показано.","why":"3-point проще повторить и использовать для проверки выхода из низкой стойки. Push-Up добавляет организацию с пола, которая пока не показала пользу для этой ошибки.","how":"Основным оставить 3-point с прежней командой выхода. Если сравнивать Push-Up, заменить им один 10-метровый повтор, не добавлять серию.","check":"Снять без перекрытий и проверить, лучше ли получается следующее обычное ускорение.","photos":[{"file":"red-pushup-crop.png","caption":"Рамир: организация ног перед выходом Push-Up; часть фона занята другим спортсменом","full":null}],"limits":"Отсутствие проверенного преимущества не означает, что упражнение бесполезно вообще. Фото Миши не выдаём за твоё.","angles":[]},"misha":{"good":"Низкое начало и сбор ног с пола сами по себе допустимы.","change":"После Push-Up туловище всё равно быстро становится высоким. Низкий первый кадр не доказывает полезного ускорения.","why":"В 3-point проще проверить твою вторую постановку стопы и следующие опоры из одинаковой готовности.","how":"Оставить 3-point основным. Для сравнения заменить Push-Up одним из назначенных 10-метровых повторов и использовать прежнюю команду.","check":"Выход вперёд и лучший следующий обычный старт, а не просто более низкая поза.","photos":[{"file":"white-pushup-crop.png","caption":"Миша: опора руками перед Push-Up","full":null},{"file":"white-ready-crop.png","caption":"Миша: готовность в 3-point для сравнения","full":null}],"limits":"Превосходство вариантов по времени не измерено; часть стоп сливается с сумкой.","angles":[]}}}]'),i=JSON.parse('[{"id":"athletics-assistant","title":"Ассистент проекта","kind":"local","candidates":"ColinEberhardt running-coach; кандидат magnus919 life-coach","decision":"Существующий местный координатор обновлён: конкретная обратная связь, отдельные люди/факты, понятные метки времени, последние уточнения пользователя","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"008041f7a615cd6a5682cd9c5e7de2ed76e9714b2a72b01d13e180a39d6f8e2e","instructions":"---\\nname: athletics-assistant\\ndescription: Вести этот проект двух начинающих спринтеров, готовить занятие, сохранять факты и восстановление, разбирать доступные видео и объяснять технику. Использовать для тренировочных вопросов в этом репозитории.\\n---\\n\\n# Ассистент по спринту\\n\\nНайди корень проекта: у него есть `docs/report.md`, `athletes/` и `plans/`. Для начала прочитай `docs/context.md`, профиль выбранного участника и относящиеся к вопросу последние занятия. Подробный отчёт загружай по нужному разделу, а не целиком для каждой короткой записи.\\n\\n## Подготовка занятия\\n\\nУточнение от 13 сентября 2026 года: пока только бег на 60 и 100 м. Не включай прыжки в длину, многоскоки и отдельные прыжковые блоки и не запрашивай доступ к яме. A-марш и A-skip остаются беговыми упражнениями действующего плана. К прыжковой подготовке возвращайся только по новому запросу пользователя; наличие справочного раздела в отчёте не отменяет это решение.\\n\\nПозднее пользователь уточнил: уже было три часа работы со стартами на 30 м, бегом на 60 и 100 м и A-, B-, C-skip примерно по 15 минут. Описана комфортная усталость и хаос из-за отсутствия фокуса. Не представляй следующее занятие как первое знакомство с этими упражнениями. B- и C-skip не запрещены из-за новичкового уровня. Для каждого занятия сначала назови одну главную задачу и роль остальных блоков. Минуты занятия не заменяют числа проходов, метров, интенсивности и отдыха; комфортная усталость сразу после занятия не подтверждает восстановление на следующие сутки.\\n\\nУстанови участника, доступную площадку и время, реакцию на прошлую нагрузку, текущую боль / болезнь, сон и работу ног за последние 48-72 часа. Уже известные сведения не спрашивай повторно. Если человек прислал только «что делать сегодня», сначала используй журнал, затем запроси лишь недостающие сведения, от которых зависит безопасность нагрузки.\\n\\nДля текущей проверки стартов используй `plans/next-start-session.md`: он заменяет прежние подводящие и основной стартовый блок. `plans/first-session.md` и `plans/12-weeks.md` сохраняют историю; их календарные нагрузки не назначать автоматически. Дай последовательность, объём, паузы, обувь, одну подсказку и условие сокращения. Отдельно считай подводящие ускорения, основные метры и метры в шиповках. Новый блок заменяет оговорённую часть прежней работы, если это предусмотрено планом.\\n\\nНе обещай разряд к дате, не назначай другу показатели первого участника. Не компенсируй пропуск удвоенным объёмом. Календарное наступление новой недели не доказывает готовность к увеличению. При боли, натяжении или хромоте прекрати советовать быстрый бег и предложи соответствующую очную оценку; не ставь диагноз по тексту.\\n\\n## Запись и недельный разбор\\n\\nПо запросу спортсмена сохрани исходные сведения в `sessions/<участник>/<дата>.md` по `templates/session.md`. Если файл существует, дополни с датой сообщения, не затирай историю. План и факт различаются; пропущенное значение не равно нулю. Неизвестные повторения не достраивай по программе.\\n\\nПосле сообщения на следующий день добавь фактическое восстановление. Для недельного разбора используй `templates/weekly-review.md`. Сравнивай время только при совместимых дистанции, старте, обуви и методе хронометража. Изменение нагрузки обоснуй наблюдаемыми сведениями; при отсутствии причины допустимо повторить неделю.\\n\\n## Видео\\n\\nДля стартов, Wall drills и первых 30 м дополнительно прочитай `../sprint-video-review/SKILL.md`; для человеческого объяснения техники — `../sprint-technique-learning/SKILL.md`, для точной пробной дозировки — `../sprint-load-planning/SKILL.md`. Пользовательские предпочтения сохранены в `docs/communication.md`. Текущий разбор исключает A/B/C и обычные СБУ по прямому запросу, но это не запрет отдельно выполнять их в разминке.\\n\\nДля передачи, приёма и хранения сначала прочитай `docs/video-workflow.md`. Принимай только указанные пользователем файлы; не сканируй всю личную медиатеку. `scripts/video_library.py` копирует и проверяет оригиналы, создаёт карточки в `videos/` и показывает наличие файлов. Дата занятия и участник берутся из сообщения, не из имени или времени копирования. Сначала проверь свободное место; внешний диск должен быть явно выбран и подключён. Автоматического удаления и фонового разбора нет.\\n\\nПеред новым просмотром найди существующую карточку и прошлый разбор, чтобы не повторять работу без причины. После просмотра сохрани текст, запиши его относительный путь в поле `review` карточки и свяжи с занятием. При наличии причины заполни `keep_reason`. Контрольная сумма различает побайтовые копии, но не разные экспорты одной попытки. Не объявляй резервную копию проверенной без сверки файлов на отдельном носителе. Метаданные телефона, исходные имена и служебные пути из местного manifest не публикуй случайно вместе с карточкой.\\n\\nПрочитай `docs/video-protocol.md`. Сначала действительно посмотри доступное движение / кадры; заголовок ролика и субтитры не заменяют визуальное наблюдение. Укажи временную шкалу, ракурс и ограничения. Сохраняй оригинал неизменным. `scripts/prepare_video.py` готовит кадры с временными метками файла и контрольной суммой; он не восстанавливает реальную скорость замедленного видео.\\n\\nРазметку делай только инструментом, сохраняющим точные исходные кадры, после проверки видимости точек. Не используй генеративные изображения для измерения техники. Если подходящего редактора нет, дай проверенные кадры и текстовые указания, прямо отметив, что разметка не выполнена.\\n\\nЗапиши наблюдение, уверенность, одну пробную подсказку и способ проверить её по `templates/video-review.md` в `reviews/<участник>/`. Не выводи силу мышц, причины травмы, активацию мышц и точный риск из положения линий. При несопоставимых ракурсах предложи повторную съёмку вместо точного численного сравнения.\\n\\nПо последнему запросу давать к каждому основному совету вертикальную карточку: собственный кадр → пример целевого действия / подписанная схема → одно ощущение → проверка и источник. Вход для телефона — `reviews/README.md`. После разрешённой отправки в закрытый GitHub в ответе использовать HTTPS-ссылку на страницу, не только местный путь. Выбранные собственные производные допускаются в `reviews/assets/`; полные оригиналы и служебные manifest остаются в `media/`. Публичный доступ не менять автоматически.\\n\\nПользователь затем явно разрешил открытое размещение («В паблик все лей»). Текущие материалы публикуются в существующем `Ramchike/athletics-reviews`, GitHub Pages `/starts/`, без повторного вопроса. Основная база сохраняется в athletics-lab. Это разрешение действует на согласованную публикацию собственных материалов; чужие оригинальные видео представлены ссылками.\\n\\n## Исследования и материалы\\n\\nБольшой обзор старта веди с `../scientific-literature-review/SKILL.md` и `../scientific-critical-thinking/SKILL.md`. Сначала проверь `docs/start-sources.md` и `docs/skill-audit.md`. Для новых навыков пользователь просит сначала искать готовые публичные аналоги; собственный модуль обосновывай по найденным ограничениям. Проверку предпосылок веди по `../coaching-assumptions/SKILL.md`, карту освоения — по `../athletics-progress-map/SKILL.md`. Не загружай все модули для короткой записи факта.\\n\\nСначала проверь `docs/sources.md` и `docs/library.md`. При новом практическом совете проверяй надёжные источники и отмечай применимость к новичку; не выдавай объём элиты за индивидуальное назначение. Новое видео заноси с автором, датой, фрагментом и реальным статусом просмотра. Не сохраняй полные чужие субтитры в публикуемой части проекта.\\n\\nДля соревнований прочитай `docs/competitions.md`, затем свежий регламент организатора. Проверяй взрослую дистанцию, а не общий список с детскими забегами. Норматив, результат и присвоенный разряд фиксируй раздельно. Не регистрируй и не оплачивай участие без запроса.\\n\\n## Имена и явная оценка детали\\n\\nПо уточнению 5 октября: Рамир — athlete-a в красном; Миша — athlete-b с белыми волосами. В новых обращениях и навигации использовать имена. Пояснять, что нормально, что изменить / проверить, почему и как; самостоятельная фраза «наклон сохраняется» недостаточна. Проверка спины обязательна как отдельный пункт наблюдения или ограничения: наклон туловища не подменяет кривизну позвоночника. См. `docs/back-and-trunk.md`.\\n","provenance":"","files":["SKILL.md"]},{"id":"sprint-video-review","title":"Видео и реальные углы","kind":"local","candidates":"jayv29 pose-analysis; yinli113 mediapipe-movement-quality","decision":"Собственный узкий модуль: реальные кадры Drive, ручная проверка стороны/контакта, углы проекции, отказ от выдуманных контактов. Найденные варианты требуют непригодных настроек или другого спорта","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"aa576cf123d06ec70bc198f8ea07c4e59a1cb8733ba3182b288a804e6a467bf9","instructions":"---\\nname: sprint-video-review\\ndescription: Разбирать видео старта и первых 30 м спринта, Wall drills и подводящих стартов; проверять человека, фазу, перспективу и линии на исходных кадрах. Не заменяет анализ СБУ или медицинскую оценку.\\n---\\n\\n# Видео старта и ускорения\\n\\nНайди корень по `.agents/skills/athletics-assistant/SKILL.md`. Прочитай `docs/video-protocol.md`, `docs/start-analysis-pipeline.md` и относящиеся к человеку прошлые разборы. Сначала посмотри движение; название файла, сообщение о намерении выполнить упражнение и результат распознавания не доказывают фактическое упражнение.\\n\\n1. Получи только переданную папку или файлы. Составь реестр с Drive ID, именем, доступностью, полнотой просмотра и человеком. Одинаковые имя и размер — кандидаты на дубли; без полной контрольной суммы тождество не доказано.\\n2. Предпочитай ограниченное чтение HTTP Range с сохранением выбранных кадров. Это получение части байтов по сети, а не «просмотр вообще без скачивания». Не сохраняй полный оригинал без необходимости; отсутствие доступных диапазонов не обходи незаметной полной загрузкой.\\n3. Сделай обзор, затем непрерывную плотную последовательность каждой выбранной попытки. По редким обзорным кадрам нельзя установить контакты или Wall Single Switch. Запиши интервал и то, что осталось вне просмотра.\\n4. Разделяй переднюю/заднюю ногу старта, опорную/маховую ногу текущего кадра, анатомическую сторону и метку модели. Проверь одежду, перекрытия и суставы вручную. Не отражай эталон ради меньшей численной разницы.\\n5. Считай контакт №1 первой новой постановкой стопы после выхода; прежнюю опору назови отдельно. Для каждого из первых 3–5 контактов проверь подход к земле, начальную опору и отрыв. Не определяй окончание толчка одним кадром.\\n6. Накладывай линии обычным редактором на копию точного кадра. Сохрани координаты, способ выбора точек, SHA-256 кадра и определения углов. Закрытую точку не достраивай. Угол на плоском изображении — проекция, не точный трёхмерный угол.\\n7. При непроверенной скорости экспорта не вычисляй реальные частоту, скорость и время опоры. Без масштаба в плоскости дорожки не назначай сантиметры шагов. Таз — ориентир движения, не измеренный центр массы всего тела; положение стопы впереди таза само по себе не доказывает торможение.\\n8. Выдай структуру 14 пунктов из `templates/start-review.md`, но не выдумывай три ошибки, если подтверждена одна. Подробности измерений оставь приложению; основной текст использует «исходная поза», «первый контакт», «третья опора». Время показывай `1:25`, при нужде `1:25,3`; сырые PTS храни в manifest.\\n\\nУглы сравнивай только при совпадении фазы, определения, упражнения и допустимого ракурса. Диапазон описаний элиты не является нормой для Wall March. Главный результат — устойчивая механика и сопоставимые 5/10/20/30 м, а не совпадение палочек. Дай каждому 1–3 команды всего, одну основную на повторение, с ощущением и способом проверить перенос.\\n\\nСначала сохрани фактические сведения занятия с неизвестными объёмами, затем отдельный пробный план. Оригиналы и служебные manifest остаются в игнорируемой `media/`. По явному запросу пользователя выбранные собственные производные для телефона хранятся в `reviews/assets/` и отправляются в существующий закрытый GitHub. К каждому основному совету показать свой кадр и целевое действие, различая референс и условную схему; обеспечить вертикальное чтение и обычную HTTPS-ссылку. HTML с встроенными кадрами тоже содержит личные данные; публичный доступ не менять автоматически.\\n\\nПозднейшее сообщение пользователя «В паблик все лей» разрешает текущую открытую публикацию в `Ramchike/athletics-reviews` с GitHub Pages. Использовать это разрешение, не спрашивать повторно для согласованной публикации. Чужие оригинальные видео не копировать вместе с собственными материалами.\\n\\n## Отдельная проверка спины\\n\\nИспользуй подтверждённые имена: Рамир (athlete-a, красный), Миша (athlete-b, белые волосы). Наклон плечо–таз, угол общей линии через таз и локальная кривизна позвоночника — разные величины. Для каждой сообщай, что измерено, видимость и ограничение; закрытую поясницу не достраивай. Два ориентира плечо/таз не дают поясничного угла. Общую прямую Wall-линии не требовать в готовности 3-point или сборе ног Push-Up. В отчёте проверять спину явно: наблюдение либо «оценить нельзя», влияние на задачу и приоритет. Основания — `docs/back-and-trunk.md`.\\n","provenance":"","files":["SKILL.md"]},{"id":"sprint-technique-learning","title":"Обучение технике","kind":"local","candidates":"ColinEberhardt running-coach; tuoxiansp socratic; K-Dense critical thinking","decision":"Готовые навыки не проверяют именно обучение Wall/старту. Местный модуль связывает упражнение, задачу, команду и проверку переноса, опираясь на научные источники","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"94d8fe65ecacbec9706e9913923100cca2e0da1532a0f68241cf1c5a1500cd85","instructions":"---\\nname: sprint-technique-learning\\ndescription: Объяснять и корректировать стартовые упражнения начинающего спринтера простыми ощущениями; выбирать допустимые ошибки, упрощение, скорость и проверку переноса в разгон.\\n---\\n\\n# Обучение механике спринта\\n\\nПрочитай `docs/technique-learning.md`, текущий разбор человека и `docs/start-research.md`. Для новой спортивной рекомендации проверь относящийся источник. Не называй тренерское упрощение доказанным законом.\\n\\nДля каждого упражнения ответь: какую конкретную наблюдаемую проблему проверяем; что обязательно сохранить; какая вариативность допустима; когда облегчить; как проверить в настоящем ускорении. Если личная ошибка неизвестна, назови упражнение пробой, а не лечением этой ошибки.\\n\\nРазличай три задачи:\\n- Положение и управление: Wall Hold/March можно упростить и замедлить, чтобы спортсмен понимал опору и сохранял положение туловища.\\n- Быстрая координация: Single Switch требует быстрой смены и контролируемого окончания; медленный марш — подготовка, а не полноценная замена.\\n- Целостное ускорение: скорость — часть задачи. Упрости исходную позу, сократи отрезок или число повторов, увеличь отдых. Не обещай перенос только от медленного выполнения.\\n\\nНебольшая ошибка не означает, что повтор бесполезен. Постоянная потеря цели упражнения не становится полезной только от количества повторений. Улучшение силовых возможностей может помочь скорости, но не гарантирует самоисправление координации. Не требуй идеального стоп-кадра до доступа к бегу.\\n\\nФормат команды: «Что видно → почему это может мешать → одна понятная команда → ожидаемое ощущение → проверка на видео/отрезке». Например: «Таз уходит назад при подъёме колена. Попробуй поднять ногу только до высоты, на которой пояс и грудь остаются на месте. Ощущение: нога двигается, туловище не помогает ей качанием». Это проба, не установленная универсальная высота бедра.\\n\\nНе давай всем одинаковую метафору. Проверяй, не вызвала ли она прыжок вверх, намеренное дотягивание стопой, чрезмерно долгую опору или скованность. «Дави дорожку назад» может быть полезнее перечисления суставов в быстром старте, но конкретный эффект для человека требует проверки. После нескольких проб проверь повтор без подсказки и на следующем занятии: улучшение во время инструкции ещё не устойчивый навык.\\n\\nPush-Up Start полезен, если низкое исходное положение помогает организовать продвижение вперёд; вреден как коррекция, если человек сначала выталкивает себя руками вверх и затем отдельно начинает бежать. 3-Point удобен для повторяемой стойки и настоящих ускорений, но не воспроизводит усилия в колодках. Перенос на колодки включает отдельное знакомство с педалями, настройками и сигналом.\\n\\n## Обращение и влияние каждой детали\\n\\nПиши «Рамир, …» и «Миша, …». Само «наклон сохраняется» не объясняет оценку. Скажи, что нормально относительно задачи, что исправлять / проверить, почему, как почувствовать и проверить. Низкий приоритет не означает отсутствия влияния. «Спина прямая» не означает устранение естественных изгибов; различай общий наклон, сгибание в тазу и форму позвоночника. Не добавляй новую команду про спину, если её ошибка не подтверждена. Сохраняй максимум 1–3 команды и одну на повтор.\\n","provenance":"","files":["SKILL.md"]},{"id":"sprint-load-planning","title":"Объём и восстановление","kind":"local","candidates":"ColinEberhardt training-plan; Lancetnik evidence-based-fitness-coach","decision":"Их нагрузки относятся к выносливости или гипертрофии. Местный модуль учитывает короткие ускорения, шиповки, зал, стороны и полный отдых; точная доза остаётся пробной","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"937fc9155c3998ec9c61fa90295fa1744f3967b3eb4838e85ea11da22222dc92","instructions":"---\\nname: sprint-load-planning\\ndescription: Составлять пробный объём занятий спринтом на 60 и 100 м из наблюдаемой задачи, переносимости и текущей нагрузки; отдельно считать Wall drills, ускорения и шиповки.\\n---\\n\\n# Дозировка под задачу\\n\\nПрочитай профиль и последние `sessions/` каждого участника, `plans/12-weeks.md`, `plans/training-map.md` и последний технический разбор. Последние пользовательские ограничения важнее календаря.\\n\\nУстанови фактическое восстановление, боль и нагрузку ног за последние 48–72 часа из доступных записей. Не переноси сведения друга и не считай старое «болей нет» подтверждением текущего состояния. Если готовность неизвестна, оформи условный пробный план и запроси только необходимое для реального выполнения.\\n\\nВыбери одну цель и 3–5 упражнений, каждое с наблюдаемой причиной включения. Не добавляй десять стартовых вариантов ради полноты каталога. Сохраняй основную практику настоящего ускорения; дополнительный drill заменяет часть прежней нагрузки.\\n\\nДля каждой строки укажи: подходы × повторы, метры или время удержания, как считать стороны, отдых между повторами/подходами, усилие, обувь, команду, критерий сокращения и критерий перехода. `2 × 5 каждой ногой` означает 20 подъёмов всего; Single Switch считают по исходной поднятой ноге. Точная дозировка — обоснованная проба, не научно установленная индивидуальная норма.\\n\\nОтдельно суммируй подводящие ускорения, основные ускорения и метры в шиповках. Не складывай статические секунды с беговыми метрами. Не превращай три часа посещения манежа в три часа быстрой нагрузки. Не дополняй новый блок полным старым планом.\\n\\nПри ухудшении качества повторов сначала дай восстановиться; если целевая механика не возвращается, сократи быстрый блок. Не увеличивай объём по календарю или одному удачному времени. При локальной боли не назначай предельный проверочный старт. Следующее усложнение зависит от повторяемости и восстановления, а не от красоты единственного кадра.\\n","provenance":"","files":["SKILL.md"]},{"id":"coaching-assumptions","title":"Проверка предположений","kind":"local","candidates":"tronghieu critical-thinking; tuoxiansp socratic; поиск Safin skills","decision":"Собственный прозрачный разбор предпосылок; не психологическая диагностика. Готовый навык Сафина не найден","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"c4d097d09f0244cb97bf91cf688565f47ed4e69f5022769ffbccb681da8ea992","instructions":"---\\nname: coaching-assumptions\\ndescription: Проверять явно высказанные спортивные гипотезы и скрытые предпосылки вопроса; объяснять без чтения мыслей, психологических диагнозов и навязанных убеждений.\\n---\\n\\n# Проверка предположений в разговоре\\n\\nПрочитай `docs/communication.md` и `docs/assumptions.md`. Пользователь просит замечать предпосылки; это разрешение обсуждать относящиеся к спорту рассуждения, а не приписывать ему психологические свойства.\\n\\nОпирайся на конкретную фразу. Раздели: сообщение о факте, оценку, предположение и следствие. Предложи трактовку «В вопросе, возможно, заложено X; поправь меня, если ты имел в виду другое». Сначала ответь на сам вопрос в доступной части. Не превращай каждую просьбу в допрос или урок психологии.\\n\\nНапример, «я сделал много сложных упражнений» может означать субъективно тяжёлую работу. Это не доказывает ни объективную координационную сложность, ни полезность, ни освоение. Не объявляй сообщение ложным; объясни, какое именно заключение из него не следует.\\n\\nДля проверяемой гипотезы запиши: формулировка пользователя; источник; что могло бы подтвердить/опровергнуть; текущий статус; следующая малая проверка. Проверяй также собственные предположения ассистента: видимость сустава, коэффициент замедления, дата, упражнение и причинная связь. Не выводи страх, лень, перфекционизм или «убеждение в голове» из одной ошибки движения или эмоционального сообщения.\\n\\nРазличай смысловую предпосылку и лингвистическую пресуппозицию (то, что фраза принимает как уже известное). Термин не требуется спортсмену для полезного объяснения. Альберт Сафин — возможный авторский ориентир общения; его высказывание не доказывает биомеханику или скрытые мотивы человека. Не называй свой навык авторизованным навыком Сафина без первичного подтверждения.\\n","provenance":"","files":["SKILL.md"]},{"id":"athletics-progress-map","title":"Карта освоения","kind":"local","candidates":"tuoxiansp socratic; WalrusQuant experiment-log/results-reporting","decision":"Собственная ограниченная карта 60/100 м и журнал проверок. Не нужен прогноз спортивных матчей или обязательное сократическое интервью","upstream":null,"license":"Местные инструкции проекта","licenseFile":null,"hash":"4c10f7127a701884cd72e5486ef5d546a2060d74c391ea81acd3e40f613ae2d5","instructions":"---\\nname: athletics-progress-map\\ndescription: Вести карту знаний и практической освоенности спринта двух участников, отмечать неизвестное и выбирать следующий полезный участок по наблюдениям и повторным проверкам.\\n---\\n\\n# Карта освоения\\n\\nИспользуй `docs/athletics-map.md` и отдельные разборы участников. Карта ограничена текущей задачей 60/100 м. Не выдавай её за измерение освоенности всей лёгкой атлетики.\\n\\nРазделяй четыре состояния: объяснение ещё не проверено; принцип объяснён; выполнена наблюдаемая проба; результат повторяется и переносится. Понимание, качество исполнения, скорость и уверенность данных — разные поля. Просмотр ролика или установленный skill не повышает автоматически качество движения спортсмена.\\n\\nОбновляй только узлы, по которым появились факты, с датой, источником и следующей проверкой. Разбор первой опоры не означает освоение 30 м. Результат без подсказки и на следующем занятии сильнее разового повторения с инструкцией.\\n\\nНе сообщай «изучено 30% спорта»: знаменатель неизвестен. Самооценку пользователя около 30% сохрани как ощущение. Если он захочет счётчик, заранее задай конечный список тем и называй долю тем со свидетельствами, отдельно от мастерства.\\n\\nВ конце существенного разбора добавь коротко: «Сейчас проверили X. Неясно Y. Следующая полезная проверка Z». Не повторяй всю карту после каждого вопроса. Новые разделы предлагай, когда они помогут текущей скорости, восстановлению или пониманию; расписания и уведомления создавай лишь по явному запросу.\\n","provenance":"","files":["SKILL.md"]},{"id":"scientific-literature-review","title":"Поиск научных работ","kind":"imported","candidates":"yigityildiz0 scientific-literature-review; K-Dense literature-review","decision":"Установлен готовый компактный scientific-literature-review. Вести реестр прочитанного, не симулировать систематический обзор","upstream":"https://github.com/yigityildiz0/scientific-agent-skills/tree/bd10a82d16dd4508c8a9daf1d98ec3c29a2db562/skills/common/scientific-literature-review","license":"MIT","licenseFile":".agents/skills/scientific-literature-review/LICENSE.txt","hash":"6a23f9c9e0e777d4c8fba17776a7e0e7e1c8466af1750015653486a03958ceec","instructions":"---\\nname: scientific-literature-review\\ndescription: \\"Builds biomedical literature searches, evidence maps and narrative/scoping/systematic-review drafts. Use for PubMed/MeSH, PICO, verified citations, research gaps and evidence updates.\\"\\nlicense: MIT\\n---\\n\\n# Scientific Literature Review\\n\\nBuild a reproducible evidence trail. Do not generate a polished narrative first and search for citations afterward.\\n\\n## Choose the review mode\\n\\n| Mode | Use when | Minimum output |\\n|---|---|---|\\n| Rapid evidence map | Time is limited; landscape and gaps matter | search log, source table, themes, gaps |\\n| Narrative review | Explain a field without claiming exhaustive coverage | scoped search, representative primary evidence, limitations |\\n| Scoping review | Map concepts, methods, or evidence types broadly | protocol, reproducible search, screening ledger, charted evidence |\\n| Systematic review | A focused question needs comprehensive, auditable selection | protocol, multi-database search, deduplication, dual/human screening plan, risk-of-bias plan, PRISMA records |\\n| Meta-analysis support | Comparable effect estimates exist | systematic-review foundation plus statistical protocol and human statistician review |\\n\\nNever call a review “systematic” merely because many sources were read.\\n\\n## Workflow\\n\\n1. Frame the question with the appropriate structure: PICO/PECO for intervention or exposure, PCC for scoping, or a mechanistic question with explicit model, perturbation, comparator, and outcome.\\n2. Predefine dates, languages, study types, populations/models, outcomes, inclusion/exclusion criteria, and treatment of preprints. Record deviations.\\n3. Build concept blocks with synonyms, gene/protein aliases, controlled vocabulary, and spelling variants. Read `references/database-search.md`.\\n4. Search PubMed plus at least one complementary database appropriate to the topic. Preserve the exact query, database, filters, search date, result count, and PubMed Search Details/translation.\\n5. Export stable identifiers and deduplicate by DOI, PMID/PMCID, accession, then normalized title/author/year. Keep a duplicate-resolution log.\\n6. Screen title/abstract and then full text against the predefined criteria. For a formal systematic review, at least two independent qualified humans make final full-text eligibility decisions and resolve disagreements by a predefined process. AI can assist; two AI agents do not satisfy independent human review. If unavailable, label the output a draft with that requirement unmet.\\n7. Extract study design, model/population, sample size, intervention/exposure, comparator, outcome, effect estimate, uncertainty, methods, funding/conflicts, and limitations into an evidence table.\\n8. Appraise evidence using a method appropriate to the study design; do not invent a universal score. Read `references/evidence-appraisal.md`.\\n9. Verify every citation against a primary bibliographic record before delivery. Read `references/citation-verification.md`.\\n10. Synthesize by evidence pattern, not paper-by-paper summary. Separate replicated findings, contested findings, methodological causes of disagreement, gaps, and inference.\\n\\nFor parallel discovery, optionally use the `deep-research` module in `research-analyst` when installed. Otherwise partition the sources within this workflow. This package remains usable by itself; retain its search log, source hierarchy, screening and citation-verification rules in either route.\\n\\n## Non-negotiable quality rules\\n\\n- Prefer primary papers for scientific claims; use reviews to orient and discover primary evidence.\\n- Label preprints, conference abstracts, retractions, corrections, and expressions of concern.\\n- Never infer full-text results from an abstract or search snippet.\\n- Quote sparingly and preserve the source\'s meaning; do not transform correlation into causation.\\n- Do not fabricate DOI, PMID, author, journal, year, sample size, effect, or quotation.\\n- Distinguish no evidence found from evidence of no effect.\\n- Report search and access limitations, unavailable full texts, and unsearched databases.\\n- Do not claim PRISMA compliance unless every applicable checklist item and flow record is complete; otherwise say “PRISMA-informed.”\\n\\n## Deliverable\\n\\nReturn:\\n\\n1. question, review mode, scope, and protocol summary;\\n2. exact search log;\\n3. inclusion/exclusion and screening summary;\\n4. evidence table with stable identifiers;\\n5. synthesis with confidence and contradictory evidence;\\n6. limitations, gaps, and recommended next searches/experiments;\\n7. verified references;\\n8. reproducibility appendix with search date and tool/database versions when available.\\n\\n## Retrieval and update references\\n\\nRead [tool-routing.md](references/tool-routing.md) for live capabilities, provenance, pagination and clipped-text handling; [search-strategy.md](references/search-strategy.md) for native clinical queries and review-mode boundaries; [literature-watch.md](references/literature-watch.md) for evidence updates. Use only the references needed for the task. Keep the user\'s scope and prior authorization within the host\'s instructions.\\n","provenance":"# Происхождение\\n\\nИсточник: https://github.com/yigityildiz0/scientific-agent-skills/tree/bd10a82d16dd4508c8a9daf1d98ec3c29a2db562/skills/common/scientific-literature-review\\n\\nИмпортирован 4 октября 2026 года: SKILL.md и шесть справочников, без изменения инструкций. Лицензия конкретного модуля MIT сохранена в LICENSE.txt. Опциональные внешние зависимости и дополнительные агенты не установлены.\\n","files":["LICENSE.txt","PROVENANCE.md","SKILL.md","references/citation-verification.md","references/database-search.md","references/evidence-appraisal.md","references/literature-watch.md","references/search-strategy.md","references/tool-routing.md"]},{"id":"scientific-critical-thinking","title":"Оценка доказательств","kind":"imported","candidates":"K-Dense scientific-critical-thinking; tronghieu critical-thinking","decision":"Установлен готовый scientific-critical-thinking: выборка, дизайн, смешение факторов и переносимость выводов","upstream":"https://github.com/K-Dense-AI/scientific-agent-skills/tree/154988403bb5a18e9d3c0ce4e6d5e2e4b184a298","license":"MIT","licenseFile":".agents/skills/scientific-critical-thinking/LICENSE.txt","hash":"7c677078a10feecde74509f2d5c2cdeef01536d641e622a4a5972c888446dc10","instructions":"---\\nname: scientific-critical-thinking\\ndescription: Evaluates scientific claims and evidence quality. Applies to experimental design validity, biases and confounders, statistical interpretation, evidence grading frameworks (GRADE, Cochrane Risk of Bias), and teaching critical analysis. Supports evidence appraisal and identifying flaws; formal peer review writing belongs to peer-review.\\nallowed-tools: Read Write Edit\\nlicense: MIT license\\nmetadata:\\n  version: \\"1.5\\"\\n  last-reviewed: \\"2026-10-01\\"\\n  skill-author: K-Dense Inc.\\n---\\n\\n# Scientific Critical Thinking\\n\\nCompatibility: Analytical guidance needs no network. Optional figures via scientific-schematics require an OPENROUTER_API_KEY and outbound OpenRouter access; this project does not enable that optional workflow.\\n\\n## Overview\\n\\nCritical thinking is a systematic process for evaluating scientific rigor. Assess methodology, experimental design, statistical validity, biases, confounding, and evidence quality using GRADE and Cochrane ROB frameworks. Apply this skill for critical analysis of scientific claims.\\n\\n## When to Use This Skill\\n\\nThis skill should be used when:\\n- Evaluating research methodology and experimental design\\n- Assessing statistical validity and evidence quality\\n- Identifying biases and confounding in studies\\n- Reviewing scientific claims and conclusions\\n- Conducting systematic reviews or meta-analyses\\n- Applying GRADE or Cochrane risk of bias assessments\\n- Providing critical analysis of research papers\\n\\n## Appraisal Workflow\\n\\n1. **Fix the question and unit.** Record population, intervention/exposure, comparator,\\n   outcome, time point, effect measure, and target setting. Distinguish descriptive,\\n   predictive, and causal claims. Identify the independent experimental/sampling unit.\\n2. **Extract evidence before judging.** Locate the numerical result, uncertainty,\\n   denominators, protocol/registration, analysis plan, and relevant supplementary material.\\n   Keep missing reporting separate from evidence that a procedure was not performed.\\n3. **Assess design and analysis.** Check selection, confounding, measurement, attrition,\\n   multiplicity, dependence, and model assumptions. Good fit or optimizer convergence does\\n   not establish a uniquely identified parameter or a causal effect.\\n4. **Choose the right appraisal framework.** Reporting completeness, risk of bias, and\\n   certainty of a body of evidence answer different questions. Record the exact tool\\n   version and the result being assessed; do not turn checklist counts into a quality score.\\n5. **Synthesize with scope intact.** Examine independent replication, overlapping samples,\\n   missing evidence, and applicability. Apply GRADE per outcome/comparison when appropriate,\\n   with explicit domain reasons, rather than grading a whole paper by its design label.\\n6. **Write a traceable critique.** For each concern give the source location, observation,\\n   consequence for the claim, uncertainty, and a feasible remedy. Separate supported\\n   conclusions from assumptions and from clinical/policy recommendations.\\n\\nCurrent framework versions, primary sources, and verification limits are in\\n[references/review_sources.md](references/review_sources.md). The examples in the references\\nare teaching examples, not empirical findings or validated patient-specific advice.\\n\\n## Visual Aids (Optional)\\n\\nOnly add figures when the **user explicitly requests** a diagram (for example, a GRADE flowchart, bias decision tree, or evidence-quality framework).\\n\\n**When figures help:**\\n- Critical thinking framework diagrams\\n- Bias identification decision trees\\n- Evidence quality assessment flowcharts\\n- GRADE or risk-of-bias evaluation frameworks\\n\\n**How to create figures:**\\n- **Preferred:** Use the **scientific-schematics** skill for AI-generated diagrams from a natural-language description\\n- **Alternative:** Build figures in your usual tools (draw.io, PowerPoint, matplotlib, etc.)\\n\\nRun from the repository root, with `OPENROUTER_API_KEY` set:\\n\\n```bash\\npython skills/scientific-schematics/scripts/generate_schematic.py \\"Illustrative GRADE appraisal: define outcome and comparison, assess certainty domains with reasons; keep recommendation decisions separate\\" -o figures/grade_flowchart.png --doc-type report\\n```\\n\\nThis optional command\'s CLI was checked with `--help`; paid generation was not exercised\\nfor this example. Follow that skill\'s current dependencies and review every generated label.\\n\\n**Disclosure:** AI schematic generation sends your prompt to [OpenRouter](https://openrouter.ai/) (a third-party API). Do not include unpublished sensitive details unless that transmission is appropriate for your project.\\n\\n---\\n\\n## Core Capabilities\\n\\nSeven capability areas, each with the questions to ask and what the answers imply, are in\\n[references/core_capabilities.md](references/core_capabilities.md):\\n\\n1. **Methodology critique** — design, controls, confounding, and whether the method can\\n   answer the question asked.\\n2. **Bias detection** — selection, measurement, publication, and cognitive biases.\\n3. **Statistical analysis evaluation** — power, multiplicity, p-value misuse, effect sizes.\\n4. **Evidence quality assessment** — study hierarchy, replication, and strength of inference.\\n5. **Logical fallacy identification** — the fallacies that recur in scientific argument.\\n6. **Research design guidance** — how to strengthen a design before data collection.\\n7. **Claim evaluation** — separating what was shown from what is being asserted.\\n\\nPer-topic detail is in [references/scientific_method.md](references/scientific_method.md),\\n[references/common_biases.md](references/common_biases.md),\\n[references/statistical_pitfalls.md](references/statistical_pitfalls.md),\\n[references/evidence_hierarchy.md](references/evidence_hierarchy.md),\\n[references/logical_fallacies.md](references/logical_fallacies.md), and\\n[references/experimental_design.md](references/experimental_design.md).\\n\\n## Application Guidelines\\n\\n### General Approach\\n\\n1. **Be Constructive**\\n   - Identify strengths as well as weaknesses\\n   - Suggest improvements rather than just criticizing\\n   - Distinguish between fatal flaws and minor limitations\\n   - Recognize that all research has limitations\\n\\n2. **Be Specific**\\n   - Point to specific instances (e.g., \\"Table 2 shows...\\" or \\"In the Methods section...\\")\\n   - Quote problematic statements\\n   - Provide concrete examples of issues\\n   - Reference specific principles or standards violated\\n\\n3. **Be Proportionate**\\n   - Match criticism severity to issue importance\\n   - Distinguish between major threats to validity and minor concerns\\n   - Consider whether issues affect primary conclusions\\n   - Acknowledge uncertainty in your own assessments\\n\\n4. **Apply Consistent Standards**\\n   - Use same criteria across all studies\\n   - Don\'t apply stricter standards to findings you dislike\\n   - Acknowledge your own potential biases\\n   - Base judgments on methodology, not results\\n\\n5. **Consider Context**\\n   - Acknowledge practical and ethical constraints\\n   - Consider field-specific norms for effect sizes and methods\\n   - Recognize exploratory vs. confirmatory contexts\\n   - Account for resource limitations in evaluating studies\\n\\n### Apply risk-of-bias tools to the right unit\\n\\nFor RoB 2, identify the specific result: outcome, time point, intervention comparison, numerical estimate, and effect of assignment versus adherence. Use the variant for individually randomized, cluster, or crossover trials; record signalling answers and justifications rather than assigning one blanket score to the whole paper. Different outcomes in the same trial can have different bias judgments. See the [Cochrane RoB 2 guidance](https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-08).\\n\\nFor non-randomized intervention effects, state whether using ROBINS-I 2016 or the\\nROBINS-I V2 November 2025 **draft** for follow-up/cohort studies. Do not mix their domains\\nor algorithms. Diagnostic accuracy appraisal now uses QUADAS-3 (current tool v1.2), at\\nthe accuracy-estimate level. See the tool-specific sources before a formal assessment.\\n\\n### When Providing Critique\\n\\n**Structure feedback as:**\\n\\n1. **Summary:** Brief overview of what was evaluated\\n2. **Strengths:** What was done well (important for credibility and learning)\\n3. **Concerns:** Issues organized by severity\\n   - Critical issues (threaten validity of main conclusions)\\n   - Important issues (affect interpretation but not fatally)\\n   - Minor issues (worth noting but don\'t change conclusions)\\n4. **Specific Recommendations:** Actionable suggestions for improvement\\n5. **Overall Assessment:** Balanced conclusion about evidence quality and what can be concluded\\n\\n**Use precise terminology:**\\n- Name specific biases, fallacies, and methodological issues\\n- Reference established standards and guidelines\\n- Cite principles from scientific methodology\\n- Use technical terms accurately\\n\\n### When Uncertain\\n\\n- **Acknowledge uncertainty:** \\"This could be X or Y; additional information needed is Z\\"\\n- **Ask clarifying questions:** \\"Was [methodological detail] done? This affects interpretation.\\"\\n- **Provide conditional assessments:** \\"If X was done, then Y follows; if not, then Z is concern\\"\\n- **Note what additional information would resolve uncertainty**\\n\\n## Reference Materials\\n\\nThis skill includes comprehensive reference materials that provide detailed frameworks for critical evaluation:\\n\\n- **`references/scientific_method.md`** - Core principles of scientific methodology, the scientific process, critical evaluation criteria, red flags in scientific claims, causal inference standards, peer review, and open science principles\\n\\n- **`references/common_biases.md`** - Comprehensive taxonomy of cognitive, experimental, methodological, statistical, and analysis biases with detection and mitigation strategies\\n\\n- **`references/statistical_pitfalls.md`** - Common statistical errors and misinterpretations including p-value misunderstandings, multiple comparisons problems, sample size issues, effect size mistakes, correlation/causation confusion, regression pitfalls, and meta-analysis issues\\n\\n- **`references/evidence_hierarchy.md`** - Traditional evidence hierarchy, GRADE system, study quality assessment criteria, domain-specific considerations, evidence synthesis principles, and practical decision frameworks\\n\\n- **`references/logical_fallacies.md`** - Logical fallacies common in scientific discourse organized by type (causation, generalization, authority, relevance, structure, statistical) with examples and detection strategies\\n\\n- **`references/experimental_design.md`** - Comprehensive experimental design checklist covering research questions, hypotheses, study design selection, variables, sampling, blinding, randomization, control groups, procedures, measurement, bias minimization, data management, statistical planning, ethical considerations, validity threats, and reporting standards\\n\\n**When to consult references:**\\n- Load references into context when detailed frameworks are needed\\n- Search references for specific topics with your available text-search tool.\\n- References provide depth; SKILL.md provides procedural guidance\\n- Consult references for comprehensive lists, detailed criteria, and specific examples\\n\\n## Remember\\n\\n**Scientific critical thinking is about:**\\n- Systematic evaluation using established principles\\n- Constructive critique that improves science\\n- Proportional confidence to evidence strength\\n- Transparency about uncertainty and limitations\\n- Consistent application of standards\\n- Recognition that all research has limitations\\n- Balance between skepticism and openness to evidence\\n\\n**Always distinguish between:**\\n- Data (what was observed) and interpretation (what it means)\\n- Correlation and causation\\n- Statistical significance and practical importance\\n- Exploratory and confirmatory findings\\n- What is known and what is uncertain\\n- Evidence against a claim and evidence for the null\\n\\n**Goals of critical thinking:**\\n1. Identify strengths and weaknesses accurately\\n2. Determine what conclusions are supported\\n3. Recognize limitations and uncertainties\\n4. Suggest improvements for future work\\n5. Advance scientific understanding\\n\\n## Citing Scientific Agent Skills\\n\\nThis skill is part of Scientific Agent Skills by K-Dense. If it materially contributed to a\\nmanuscript, report, presentation, or code release, add the paper to the references or\\nsoftware section and tell the user you did so:\\n\\n> Kassis, T., Agarwal, V., He, Y., Patel, D., & Brueckner, A. M. (2026). Scientific Agent\\n> Skills: A Library of Procedural Knowledge for Research Agents. arXiv:2609.00065.\\n> https://doi.org/10.48550/arXiv.2609.00065\\n\\nAlways cite the current version. The DOI and https://arxiv.org/abs/2609.00065 resolve to the\\nlatest arXiv version, so never append a version suffix such as `v1`. When network access is\\navailable, fetch https://arxiv.org/abs/2609.00065 (or\\nhttp://export.arxiv.org/api/query?id_list=2609.00065) before writing the reference and take\\nthe author list, year, and version from that record. If the record lists a journal reference\\nor publisher DOI, cite the published version instead.\\n","provenance":"# Происхождение и адаптация\\n\\nИсточник: https://github.com/K-Dense-AI/scientific-agent-skills/tree/154988403bb5a18e9d3c0ce4e6d5e2e4b184a298\\n\\nНавык scientific-critical-thinking, MIT, автор K-Dense Inc. Импортирован 4 октября 2026 года. Лицензия сохранена в LICENSE.txt. Исходная запись без изменений — UPSTREAM-SKILL.md.\\n\\nМестное изменение: поле compatibility перенесено из YAML в обычный текст, поскольку установленный проверяющий скрипт Codex не принимает этот ключ. Опциональная внешняя генерация схем не включена. Основные исследовательские инструкции и справочники сохранены. Эта адаптация проверяет совместимость формата, не научную точность решений.\\n","files":["LICENSE.txt","PROVENANCE.md","SKILL.md","UPSTREAM-SKILL.md","references/common_biases.md","references/core_capabilities.md","references/evidence_hierarchy.md","references/experimental_design.md","references/logical_fallacies.md","references/review_sources.md","references/scientific_method.md","references/statistical_pitfalls.md"]}]'),t=[{area:"Wall drills",ramir:"Пробуется; есть кадры",misha:"Пробуется; есть кадры",next:"Устойчивая линия при одиночной смене, затем обычный старт"},{area:"Falling Start",ramir:"Выбранный выход и пять опор разобраны; наклон сохраняется дольше, чем в выбранном низком старте",misha:"Пригодная попытка разгона пока не подтверждена: просмотренный эпизод — объяснение с жестами",next:"Снять назначенные две попытки, без дополнительной нагрузки"},{area:"3-point / низкий старт без колодок",ramir:"Выбрана низкая попытка с рукой; быстрый подъём, усилие неизвестно",misha:"3-point подтверждён; вторая стопа впереди колена, быстрый подъём туловища",next:"Одинаковое намерение ускоряться до 10 м; первые пять контактов сбоку"},{area:"Push-Up Start",ramir:"Опора руками и выход видны; часть контактов закрывают бегуны",misha:"Выход виден, быстрый подъём сохраняется; точная нумерация части опор ненадёжна",next:"Если сравнивать, заменить один назначенный 3-point, снять сбоку без перекрытия"},{area:"Ускорение 5–10 м",ramir:"Пробуется; сопоставимых времён нет",misha:"Пробуется; сопоставимых времён нет",next:"Одинаковая дистанция и процедура измерения"},{area:"Ускорение 20–30 м",ramir:"Обсуждалось; границы дистанций на видео неизвестны",misha:"Обсуждалось; границы дистанций на видео неизвестны",next:"Разметка дорожки и непрерывная попытка"},{area:"Колодки",ramir:"Не исследовано на практике в этом разборе",misha:"Не исследовано на практике в этом разборе",next:"Знакомство после доступа к колодкам"},{area:"Реакция на сигнал",ramir:"Не измерена",misha:"Не измерена",next:"Звук и движение в одном источнике, без неизвестного замедления"},{area:"Максимальная скорость",ramir:"За пределами текущего разбора",misha:"За пределами текущего разбора",next:"Отдельная задача и съёмка"},{area:"Скоростная выносливость",ramir:"За пределами текущего разбора",misha:"За пределами текущего разбора",next:"Не добавлять в занятие автоматически"},{area:"Сила и восстановление",ramir:"Есть самоописание, объективных тестов нет",misha:"Индивидуальные данные неполны",next:"Запись зала за 48–72 часа и реакции на бег"},{area:"Соревнования и нормативы",ramir:"Цель сообщена; разряд не подтверждён",misha:"Индивидуальная цель не подтверждена",next:"Актуальные документы и официальный результат"}],a=[{request:"Сначала найти готовые навыки для каждого направления",done:"Поиск и аудит восьми направлений, десяти репозиториев; два готовых научных модуля установлены, пять местных написаны по выявленным ограничениям",next:"Это проверка содержания и формата, не независимая проверка качества тренерских решений. [Аудит](skill-audit.md)"},{request:"Сохранить стиль общения и прошлые ошибки",done:"Обновлены AGENTS.md, координатор и [предпочтения](communication.md); сохранены понятные метки времени, одна команда, разделение факта и гипотезы",next:"Использованы текущий разговор и документы. Недоступные прошлые чаты не прочитаны; психологические причины раздражения не выдуманы"},{request:"Исследовать не меньше 20 источников",done:"21 научная работа: пять полных текстов/относящихся разделов, 16 аннотаций; дополнительно российские, американские, австралийские и исторические материалы",next:"Не все работы прочитаны полностью; это целевой обзор. [Реестр статусов](start-sources.md), [выводы](start-research.md)"},{request:"Посмотреть 10–20 визуальных материалов",done:"Выборки кадров из 15 видео, включая четыре ALTIS, Landow, пользовательские референсы и советский фильм",next:"Это выбранные кадры, не просмотр всех 15 целиком со звуком; A/B/C и повторный монтаж одного забега не независимые подтверждения"},{request:"Советские материалы",done:"Выборка фильма о Борзове 1978 года, выбранные страницы его книги, 14 кадров диафильма Рохлина 1971 года и весь доступный текст его подписей",next:"Только один советский фильм визуально проверен; 10–20 советских фильмов не просмотрены. Несколько архивных страниц доступны лишь как каталоги"},{request:"Определить упражнения новой папки",done:"Обзор восьми выбранных источников, затем плотные выборки Wall, Falling, Push-Up и низких стартов",next:"Папка содержит длинные записи; все повторения не проаудированы. 4-point и Reaction отдельно не подтверждены"},{request:"Наложить линии и оценить углы",done:"Ручная разметка реальных Wall-кадров обоих, выбранных первых опор Рамира и Миши; чувствительность Wall-точек проверена",next:"Косой низкий ракурс: углы проекции. Скрытые суставы не измерены. [Разбор с изображениями](../reviews/2026-10-04-starts.md)"},{request:"Первые 3–5 контактов каждого",done:"Пять опор Рамира в Falling и низком старте, области первых пяти опор Миши в 3-point описаны отдельно",next:"Часть Push-Up закрывают бегуны/сумка. Не все касания найдены с точностью до первого кадра; полноценный Falling Миши не подтверждён"},{request:"Сравнить Push-Up и 3-point",done:"Для обоих основным предложен 3-point; причины и ограничения отдельны",next:"Превосходство по времени не проверено. Если сравнивать, заменить один назначенный повтор, снять без перекрытий"},{request:"Объяснить «плохо», «идеально», «медленно»",done:"Разобраны гипотезы, связь цели упражнения с темпом и допустимым отклонением",next:"Рост силы не равен автоматическому обучению. [Обучение](technique-learning.md), [предпосылки](assumptions.md)"},{request:"Навыки Сафина / убеждения",done:"Публичный готовый skill искался, не найден; написан прозрачный модуль проверки предпосылок",next:"Не приписывать скрытое убеждение и не выдавать психологическую диагностику за работу с формулировкой"},{request:"Понятная карта освоения",done:"[Карта 60/100 м](athletics-map.md) с отдельными статусами людей и следующими проверками",next:"Процент всей лёгкой атлетики не вычисляется; красивый кадр не означает освоение"},{request:"Итог из 14 пунктов и 1–3 команды каждому",done:"[Общий отчёт](../reviews/2026-10-04-starts.md), [Рамир](../reviews/athlete-a/2026-10-04-starts.md), [Миша](../reviews/athlete-b/2026-10-04-starts.md)",next:"Три направления исправления не выданы за три доказанные причины медленного результата"},{request:"3–5 упражнений и точный объём",done:"Пять упражнений, паузы, обувь, отдельные метры и условия сокращения в [пробном плане](../plans/next-start-session.md)",next:"Будущий условный план заменяет старые подводящие и стартовый блок; неизвестный факт занятия им не заполнен"},{request:"Цель: быстрее 5/10/20/30 м",done:"Подготовлен способ сопоставимой проверки и требования к пересъёмке",next:"Выигрыш не измерен: нет подтверждённой временной шкалы и отметок. Перенос в колодки пока не проверен"}],s=[{idea:"«Могу делать плохо, мышцы прокачаются, потом будет хорошо»",finding:"Физические качества могут улучшаться без нужного изменения координации. Автоматическое исправление движения не доказано. Допустимы отдельные неудачные попытки, если задача понятна и следующая попытка меняется",check:"Снять тот же старт после подводящего упражнения и на следующем занятии без напоминания"},{idea:"«Нужно делать идеально; если не могу, делаю медленнее»",finding:"Медленный темп помогает собрать позу. Быструю смену и ускорение нельзя освоить только медленным выполнением: условия движения отличаются",check:"После освоенного медленного движения добавить одиночную быструю смену, затем проверить настоящий разгон"},{idea:"«Сложное упражнение уже сделал»",finding:"Сложность и польза — разные вопросы. Сам факт выполнения не подтверждает попадание в задачу",check:"Уточнить, какой элемент должен был измениться и изменился ли он"},{idea:"«Нога к середине живота»",finding:"Это возможный образ, но в Wall drill он может вызвать лишнее сгибание корпуса или завышенный подъём колена",check:"Проверить, двигается ли бедро при устойчивом тазе; если корпус складывается, сменить образ"},{idea:"«Эталон элиты надо повторять»",finding:"Общие механические задачи полезны; точные углы и длины зависят от скорости, силы, пропорций и фазы",check:"Сравнивать одинаковые фазы и собственный результат, а не сходство силуэта"},{idea:"«Без колодок готовимся к колодкам»",finding:"Разгон и организация первого шага частично общие. Две педали, задняя опора, положение рук и реакция требуют отдельного освоения",check:"После появления колодок сначала проверить настройку и первые контакты, затем сравнить 10 м"}],r=JSON.parse('{"audit":"# Проверка готовых навыков\\n\\nДата: 4 октября 2026 года. По прямому запросу пользователя готовые варианты искались **для каждого направления**, прежде чем писать местный модуль. Наличие SKILL.md и слово evidence-based не подтверждают качество рекомендаций. Проверка относится к указанным версиям, а не ко всем будущим изменениям репозитория.\\n\\n## Решение для каждого направления\\n\\n| Направление / местный навык | Найденные готовые кандидаты | Решение и причина |\\n| --- | --- | --- | --- |\\n| Работа с научной литературой | yigityildiz0 scientific-literature-review; K-Dense literature-review | Установлен готовый компактный scientific-literature-review. Вести реестр прочитанного, не симулировать систематический обзор |\\n| Оценка доказательств | K-Dense scientific-critical-thinking; tronghieu critical-thinking | Установлен готовый scientific-critical-thinking: выборка, дизайн, смешение факторов и переносимость выводов |\\n| sprint-video-review | jayv29 pose-analysis; yinli113 mediapipe-movement-quality | Собственный узкий модуль: реальные кадры Drive, ручная проверка стороны/контакта, углы проекции, отказ от выдуманных контактов. Найденные варианты требуют непригодных настроек или другого спорта |\\n| sprint-technique-learning | ColinEberhardt running-coach; tuoxiansp socratic; K-Dense critical thinking | Готовые навыки не проверяют именно обучение Wall/старту. Местный модуль связывает упражнение, задачу, команду и проверку переноса, опираясь на научные источники |\\n| sprint-load-planning | ColinEberhardt training-plan; Lancetnik evidence-based-fitness-coach | Их нагрузки относятся к выносливости или гипертрофии. Местный модуль учитывает короткие ускорения, шиповки, зал, стороны и полный отдых; точная доза остаётся пробной |\\n| coaching-assumptions | tronghieu critical-thinking; tuoxiansp socratic; поиск Safin skills | Собственный прозрачный разбор предпосылок; не психологическая диагностика. Готовый навык Сафина не найден |\\n| athletics-progress-map | tuoxiansp socratic; WalrusQuant experiment-log/results-reporting | Собственная ограниченная карта 60/100 м и журнал проверок. Не нужен прогноз спортивных матчей или обязательное сократическое интервью |\\n| athletics-assistant и предпочтения общения | ColinEberhardt running-coach; кандидат magnus919 life-coach | Существующий местный координатор обновлён: конкретная обратная связь, отдельные люди/факты, понятные метки времени, последние уточнения пользователя |\\n\\n## Репозитории и зафиксированные версии\\n\\n| Первичный репозиторий | Версия | Лицензия / состояние проверки | Решение |\\n| --- | --- | --- | --- |\\n| [ColinEberhardt/claude-running-coach](https://github.com/ColinEberhardt/claude-running-coach/tree/c1546f47712ff3100d7443cd032963edd54ddb1f) | `c1546f47712ff3100d7443cd032963edd54ddb1f` | MIT | Не установлен: планы 5 км–марафон, расчёт темпов и объёма на выносливость. Коммуникация местами требует поддерживающей похвалы; автоматическая календарная прогрессия не подходит текущей задаче. |\\n| [K-Dense-AI/scientific-agent-skills](https://github.com/K-Dense-AI/scientific-agent-skills/tree/154988403bb5a18e9d3c0ce4e6d5e2e4b184a298) | `154988403bb5a18e9d3c0ce4e6d5e2e4b184a298` | MIT | Установлен только scientific-critical-thinking. Большой literature-review найден, но выбран более компактный отдельный вариант; платные/внешние исследовательские зависимости не запускались. |\\n| [Lancetnik/evidence-based-fitness-coach](https://github.com/Lancetnik/evidence-based-fitness-coach/tree/2665ccb4d58d563c5eb3bb8d371b79e7035e0fbb) | `2665ccb4d58d563c5eb3bb8d371b79e7035e0fbb` | MIT | Не установлен: специализация на гипертрофии/составе тела и питании. Полезные общие ограничения не делают его навыком спринтерской дозировки. |\\n| [WalrusQuant/sports-analytic-skills](https://github.com/WalrusQuant/sports-analytic-skills/tree/0f90d2463b7d4c793821cce71fc82d06fcb06a3c) | `0f90d2463b7d4c793821cce71fc82d06fcb06a3c` | NOASSERTION | Не установлены experiment-log/results-reporting: спортивные прогнозы и статистика соревнований, не кинематика человека. Взята общая идея журналировать все попытки; их модели NFL/NBA/MLB не перенесены. |\\n| [jayv29/pose-analysis-skill](https://github.com/jayv29/pose-analysis-skill/tree/476a6cbcf10f44bd478327934a62dce605ca8ced) | `476a6cbcf10f44bd478327934a62dce605ca8ced` | MIT | Не установлен: локальные macOS/iCloud пути, обязательный китайский ответ, другие спортивные задачи и определение спорта по имени. Полезен как проверка требований к видимости, не как готовый анализ спринта. |\\n| [magnus919/agent-skills](https://github.com/magnus919/agent-skills/tree/9b34a87ee729f109019ac604681e5796349ea1b2) | `9b34a87ee729f109019ac604681e5796349ea1b2` | MIT | Кандидат life-coach найден поиском, но актуальный SKILL.md не подтверждён в полученном дереве. Не установлен и не считается содержательно проверенным навыком. |\\n| [tronghieu/agent-skills](https://github.com/tronghieu/agent-skills/tree/2fce93c84ddd0e9f38a48a82a9a16644d6c9d906) | `2fce93c84ddd0e9f38a48a82a9a16644d6c9d906` | MIT | Не установлен critical-thinking: полезная проверка аргументов, но обязательная предварительная фиксация собственного ответа пользователем может задерживать прямую техническую помощь. Для научной оценки выбран другой готовый навык. |\\n| [tuoxiansp/socratic](https://github.com/tuoxiansp/socratic/tree/d474e0a7091ee19523147901b9c754f758d2656b) | `d474e0a7091ee19523147901b9c754f758d2656b` | Не обнаружена | Не установлен: схема учебной карты полезна, но запрещает прямой ответ до попытки учащегося; лицензия импорта не обнаружена. Собственная карта не выдаёт понимание за исполнение движения. |\\n| [yigityildiz0/scientific-agent-skills](https://github.com/yigityildiz0/scientific-agent-skills/tree/bd10a82d16dd4508c8a9daf1d98ec3c29a2db562) | `bd10a82d16dd4508c8a9daf1d98ec3c29a2db562` | NOASSERTION | Установлен common/scientific-literature-review с собственным LICENSE.txt (MIT). Лицензия корня распознана GitHub неоднозначно, поэтому проверен именно установленный модуль. |\\n| [yinli113/mediapipe-movement-quality](https://github.com/yinli113/mediapipe-movement-quality/tree/a954eed3978a0ee575f283732b8c9c0277d04998) | `a954eed3978a0ee575f283732b8c9c0277d04998` | Не обнаружена | Не установлен: инженерная проверка MediaPipe, событий и отображения; много гольфовых правил. В репозитории не обнаружена лицензия, разрешающая импорт. Идея отличать обнаруженный сигнал от подтверждённой фазы учтена своим текстом. |\\n\\nСодержательно проверены целевые записи и относящиеся к ним инструкции; не весь код всех репозиториев. Сторонние команды из найденных навыков не выполнялись. Не установлены дополнительные агенты, расписания, OpenRouter и интеграции Strava. Источники лицензий сохранены рядом с двумя установленными модулями.\\n\\n## Установлено в проекте\\n\\n- [scientific-literature-review](../.agents/skills/scientific-literature-review/SKILL.md): версия исходного репозитория `bd10a82d16dd4508c8a9daf1d98ec3c29a2db562`, инструкции и справочники поиска/проверки цитат.\\n- [scientific-critical-thinking](../.agents/skills/scientific-critical-thinking/SKILL.md): версия `154988403bb5a18e9d3c0ce4e6d5e2e4b184a298`, entry указывает версию навыка 1.5 и проверку 2026-10-01.\\n- Пять узких местных модулей: [видео](../.agents/skills/sprint-video-review/SKILL.md), [обучение](../.agents/skills/sprint-technique-learning/SKILL.md), [дозировка](../.agents/skills/sprint-load-planning/SKILL.md), [предпосылки](../.agents/skills/coaching-assumptions/SKILL.md), [карта](../.agents/skills/athletics-progress-map/SKILL.md). Это процедуры ассистента, не сертифицированные тренеры и не модели с доказанной точностью распознавания техники.\\n- [AGENTS.md](../AGENTS.md) и основной athletics-assistant связывают маршруты. Автоматическая доступность новых записей в каталоге зависит от обновления сессии; текущая работа использует прочитанные инструкции прямо из файлов.\\n\\n## Ограничения проверки\\n\\nАвторы большой библиотеки описали её в [Scientific Agent Skills: A Library of Procedural Knowledge for Research Agents, Kassis et al., 2026](https://doi.org/10.48550/arXiv.2609.00065). Это препринт о библиотеке процедур; он не доказывает качество наших спортивных решений и не предоставляет независимой проверки точности анализа ваших видео. Следующий критерий качества здесь — сопоставимое наблюдение и измеряемый перенос в разгон.\\n\\nПри проверке совместимости установленный валидатор Codex отклонил YAML-поле `compatibility` у scientific-critical-thinking. Его содержимое перенесено в обычный текст; исходная запись сохранена в `UPSTREAM-SKILL.md`, изменение описано в `PROVENANCE.md`. Остальные инструкции не менялись. Это местная адаптация формата, а не дословно неизменённый импорт.\\n\\nПубличный навык может содержать команды на отправку данных, установку пакетов или публикацию. Включение навыка не является отдельным разрешением на эти действия; пользовательский запрос и правила проекта имеют приоритет. Перед обновлением зафиксированных версий повторно проверять существенные изменения.\\n\\n## Как проверять местные навыки\\n\\nКонтрольные ситуации: неизвестное замедление → нет истинной частоты; косой кадр → нет точного 3D-угла; скрытая стопа → нет подтверждённого контакта; красивый drill → нет заявления об улучшении 10 м; неизвестные повторы → не заполнять факт дозировкой; три часа манежа → не три часа быстрых стартов; другой человек в красном → не автоматическая идентификация; спор о предпосылке → цитата и проверка, не диагноз. Проверка геометрии скрипта отделена от проверки точности вручную выбранных суставов.\\n\\n## Корневая загрузка: 5 октября\\n\\nВ athletics-reviews полный активный набор перенесён в корневую `.agents/skills/`; рядом корневой AGENTS.md и рабочие документы. Навигационный каталог — `/skills/`, ссылки ведут на реальные SKILL.md в GitHub, отдельно показаны два готовых и шесть местных модулей. Лицензии, справочники, происхождение и зафиксированные версии готовых модулей сохранены.\\n\\n[Официальная документация Codex](https://learn.chatgpt.com/docs/build-skills#where-codex-loads-local-skills), проверена 5 октября: Codex ищет `.agents/skills` от текущей папки вверх до корня репозитория; вложенный materials не является этим маршрутом при старте из корня. Изменения обычно обнаруживаются автоматически; при отсутствии навыка в каталоге можно перезапустить Codex. Это инструкция для Codex, не гарантия одинакового поведения любого другого агента.\\n\\nСтарые HTML-страницы навыков сохранены; их текстовые SKILL.md в materials переименованы в ARCHIVED-SKILL.md, чтобы не создать дубли активных имён при старте из подпапки. Работа из корня и пересборка сайта без оригиналов видео проверяются отдельно от точности спортивного анализа.\\n","sources":"# Источники по старту, разгону и обучению\\n\\nПоиск и проверка: 4 октября 2026 года. Это целевой обзор, не зарегистрированный систематический обзор и не метаанализ автора проекта. Искались первичные исследования и обзоры, затем материалы самих тренеров/организаций. Готовые навыки аудированы отдельно: их репозитории не входят в число спортивных источников.\\n\\nНиже **21 научный источник**: 5 полных текстов/относящихся к задаче разделов и 16 аннотаций. Аннотация позволяет осторожно указать опубликованный результат, но не заменяет проверку всех методов и риска систематической ошибки. Дополнительно есть российский сборник, российская аннотация и тренерские материалы; таким образом рассмотрено более 20 разных источников, без подсчёта зеркал одной статьи.\\n\\n## Научные источники\\n\\n| № | Источник | Что прочитано | Применимость и ограничения |\\n| --- | --- | --- | --- |\\n| 1 | [Guadagnoli MA, Lee TD. 2004. Challenge point: a framework for conceptualizing the effects of various practice conditions in motor learning](https://doi.org/10.3200/jmbr.36.2.212-224) | Аннотация | Теоретическая модель сложности обучения: трудность зависит от подготовленности и условий; не доказательство, что любой плохой повтор полезен. |\\n| 2 | [Kugler F, Janshen L. 2010. Body position determines propulsive forces in accelerated running](https://doi.org/10.1016/j.jbiomech.2009.07.041) | Аннотация | 41 физически активный участник: связь положения тела и направления движущей силы. Не клинический тест и не универсальные 45°. |\\n| 3 | [Wulf G, Shea CH, Matschiner S. 1998. Frequent feedback enhances complex motor skill learning](https://doi.org/10.1080/00222899809601335) | Аннотация | Два эксперимента со сложной координационной задачей: частая обратная связь иногда полезна. Правило «чем реже подсказки, тем лучше» не универсально. |\\n| 4 | [Morin JB, Edouard P, Samozino P. 2011. Technical ability of force application as a determinant factor of sprint performance](https://doi.org/10.1249/mss.0b013e318216ea37) | Аннотация | Небольшая смешанная выборка: связь направления приложения силы с результатом. Корреляция не назначает угол корпуса и не измеряет силы по фото. |\\n| 5 | [Nagahara R, Naito H, Morin JB, Zushi K. 2014. Association of acceleration with spatiotemporal variables in maximal sprinting](https://doi.org/10.1055/s-0033-1363252) | Аннотация | 21 мужчина: связи ускорения с частотой и длиной по фазам. Не план длины каждого шага в сантиметрах. |\\n| 6 | [Nagahara R, Matsubayashi T, Matsuo A, Zushi K. 2014. Kinematics of transition during human accelerated sprinting](https://doi.org/10.1242/bio.20148284) | Аннотация | 12 мужчин, разгон на 60 м: последовательные изменения позы и контакта. Не требовать стопу позади центра массы на всех шагах. |\\n| 7 | [Seitz LB, Reyes A, Tran TT, Saez de Villarreal E, Haff GG. 2014. Increases in lower-body strength transfer positively to sprint performance: a systematic review with meta-analysis](https://doi.org/10.1007/s40279-014-0227-1) | Аннотация | 15 исследований, 510 участников: силовые улучшения могут переноситься в скорость. Это не доказательство автоматического исправления координации. |\\n| 8 | [Rabita G, Dorel S, Slawinski J, Sàez-de-Villarreal E, Couturier A, Samozino P, Morin JB. 2015. Sprint mechanics in world-class athletes: a new insight into the limits of human locomotion](https://doi.org/10.1111/sms.12389) | Аннотация | 9 очень быстрых мужчин: связь скорости и механических показателей. Маленькая элитная выборка, ограниченная применимость к новичкам. |\\n| 9 | [Brazil A, Exell T, Wilson C, Willwacher S, Bezodis IN, Irwin G. 2018. Joint kinetic determinants of starting block performance in athletic sprinting](https://doi.org/10.1080/02640414.2017.1409608) | Аннотация | 17 мужчин-спринтеров: механика обеих опор в колодках. Задняя нога тоже создаёт действие на педаль; без педали условия другие. |\\n| 10 | [Bezodis NE, Willwacher S, Salo AIT. 2019. The Biomechanics of the Track and Field Sprint Start: A Narrative Review](https://doi.org/10.1007/s40279-019-01138-1) | Полный текст | Обзор стартовой позы, выхода и первых опор. Нет единственной оптимальной комбинации углов; описательные величины элиты не являются индивидуальными целями. |\\n| 11 | [Aoyagi Y, Ohnishi E, Yamamoto Y, Kado N, Suzuki T, Ohnishi H, Hokimoto N, Fukaya N. 2019. Feedback protocol of \'fading knowledge of results\' is effective for prolonging motor learning retention](https://doi.org/10.1589/jpts.31.687) | Аннотация | 46 взрослых, изометрическая задача плеча: уменьшение обратной связи и сохранение навыка. Косвенно для спринта; не назначает частоту наших команд. |\\n| 12 | [Li D, Zhang L, Yue X, Memmert D, Zhang Y. 2022. Effect of Attentional Focus on Sprint Performance: A Meta-Analysis](https://doi.org/10.3390/ijerph19106254) | Аннотация | 6 исследований, 166 участников: небольшой средний эффект внешнего фокуса внимания. Преимущественно ближайший результат, не гарантия долгосрочного обучения. |\\n| 13 | [Thurlow F, Weakley J, Townshend AD, Timmins RG, Morrison M, McLaren SJ. 2023. The Acute Demands of Repeated-Sprint Training on Physiological, Neuromuscular, Perceptual and Performance Outcomes in Team Sport Athletes: A Systematic Review and Meta-analysis](https://doi.org/10.1007/s40279-023-01853-w) | Аннотация | Метаанализ краткого отдыха и повторных спринтов в игровых видах. Подтверждает существенные острые требования; не дозировка качественных стартов с полным отдыхом. |\\n| 14 | [Ward C, Catháin CÓ, Chéilleachair NN, Grassick S, Kelly DT. 2024. Does Resisted Sprint Training Improve the Sprint Performance of Field-Based Invasion Team Sport Players? A Systematic Review and Meta-analysis](https://doi.org/10.1007/s40279-023-01952-8) | Аннотация | 21 исследование в игровых видах: улучшение внутри группы не равно превосходству над обычным спринтом. |\\n| 15 | [Aldrich EK, Sullivan K, Wingo JE, Esco MR, Leeper J, Richardson MT, Winchester LJ, Fedewa MV. 2024. The Effect of Resisted Sprint Training on Acceleration: A Systematic Review and Meta-Analysis](https://doi.org/10.70252/vkav1115) | Аннотация | 15 исследований: преимущество сопротивления над сопоставимой обычной практикой ускорения не было убедительным. Не объявлять санки обязательными. |\\n| 16 | [Myrvang S, van den Tillaar R. 2024. The Longitudinal Effects of Resisted and Assisted Sprint Training on Sprint Kinematics, Acceleration, and Maximum Velocity: A Systematic Review and Meta-analysis](https://doi.org/10.1186/s40798-024-00777-7) | Аннотация | 21 исследование: результаты зависят от дистанции и метода. Отдельный эффект 10 м не означает универсального улучшения 20–30 м или техники. |\\n| 17 | [Xu K, Jukic I, Cross MR, Hicks DS, Yin M, Zhong Y, Tang W, Li Y, Liang Z, Wang R, Morin JB, Girard O. 2025. Effects of Resisted-Sprint Training on Sprint Performance and Mechanics: A Systematic Review and Meta-Analysis Focusing on Load Magnitude](https://doi.org/10.1111/sms.70182) | Аннотация | Метаанализ нагрузки сопротивления, 2025: эффекты зависят от группы и нагрузки. Не переносить тяжёлые сопротивления на наших новичков по одной позе. |\\n| 18 | [Biomechanical Performance Factors in the Track and Field Sprint Start: A Systematic Review](https://doi.org/10.3390/ijerph19074074) | Полный текст | Систематический обзор 36 работ: учитывать фазу и уровень, не выводить единственный эталон позы. |\\n| 19 | [Inter- and intra-limb coordination during initial sprint acceleration](https://doi.org/10.1242/bio.059501) | Полный текст | Последовательность межсуставной координации меняется на первых шагах. Кадр первого выхода не эталон всех следующих контактов. |\\n| 20 | [Thinking Outside the Block: External Focus of Attention Improves Reaction Times and Movement Preparation Times in Collegiate Track Sprinters](https://doi.org/10.3390/sports6040120) | Полный текст | 12 спринтеров колледжа: внешняя команда и ближайшая реакция/подготовка движения. Не доказательство улучшения 100 м. |\\n| 21 | [Haugen et al., 2019. The Training and Development of Elite Sprint Performance](https://doi.org/10.1186/s40798-019-0221-0) | Разделы о технике, индивидуализации, нагрузке и ускорении | Соединяет науку и тренерскую практику; многие схемы элиты не проверены прямым сравнением. Наши числа повторов им не устанавливаются. |\\n\\n## Россия, США и тренерская практика\\n\\n| № | Источник | Статус | Что берём / что не берём |\\n| --- | --- | --- | --- |\\n| 22 | [Тютиков П. А., Войнова С. Е. Современные тенденции развития техники низкого старта. Сборник НГУ Лесгафта, 2017, с. 487–490](https://lesgaft.spb.ru/sites/default/files/u1/upload/m2.pdf) | Прочитаны страницы статьи, в том числе методы и таблицы | Видеопроверка первых трёх шагов. Эксперимент всего с двумя КМС, сравнение с элитой, в таблице есть подозрительная запись длительности: не назначаем описанные углы/высоты и не обещаем указанный выигрыш. |\\n| 23 | [Основы тренировки бега на короткие дистанции в лёгкой атлетике — журнал Лесгафта](https://uchzapiski.lesgaft.spb.ru/ru/nauka/article/118765/view) | Страница публикации и аннотация; полный текст не проверен | Российская методическая перспектива. Не используем как основание точной дозы или диагноза по углу. |\\n| 24 | [Loren Landow / NSCA. Bridge: Coaching Acceleration, 2016](https://www.nsca.com/education/videos/bridge-series/the-bridge-coaching-acceleration/) | Текст страницы; видео доступно через YouTube, отдельно в реестре ниже | Тренерская прогрессия от контроля позы к движению. Это мнение тренера, не контролируемое доказательство переноса Wall drills. |\\n| 25 | [Athletics Australia: Three Great Acceleration Drills — Landow](https://coachathletics.com.au/coaching-education/three-great-acceleration-drills-loren-landows-drill-progression) | Описание прогрессии | Дополняет материал NSCA; просмотрена схема Wall1.png: бедро примерно перпендикулярно линии туловища. Это конкретная тренерская модель, а не установленный универсальный диапазон. Один автор/метод не считается независимым подтверждением. |\\n| 26 | [Fast Five: Wall March and Wall Switch / CoachTube](https://coachtube.com/course_lesson/drills-to-improve-sprint-performance/fast-five-wall-march-and-wall-switch/18411620) | Страница урока; видео урока не просмотрено из-за доступа | Указатель тренерского материала. Не утверждаем, что его демонстрация визуально проверена. |\\n\\n## Советские материалы\\n\\n- [Э. И. Рохлин. «Бег на короткие дистанции», диафильм, 1971](https://www.allforchildren.ru/diafilm/diafilm419.php): прочитано описание и текст; визуально проверены 14 сканированных кадров, включая последовательность старта 16–21 и выходные данные. Это школьное учебное пособие с рисунками/кинограммами, а не видео. Указания о полном выпрямлении ноги и величины элитного шага не переносим буквально в наши первые опоры. Публикация сканов — современный сторонний архив, авторство первичного пособия видно на последнем кадре.\\n\\n\\n- [Лёгкая атлетика. Бег. Олимпиада-80, 1981, NetFilm](https://www.net-film.ru/film-38786/): прочитано описание каталога; HTML плеера не подтверждает доступность самого фильма, доступ расходится с индексом поиска. Не считается просмотренным видео и не основание измерения углов.\\n- [Московский стадион Динамо, 1949, NetFilm](https://www.net-film.ru/film-57305/): каталог описывает тренировочные эпизоды; движение пока не просмотрено. Историческая хроника не автоматически материал о старте на 60/100 м.\\n- [Секреты королевы спорта, 1970, NetFilm](https://www.net-film.ru/film-50954/): найден архивный материал с Борзовым; доступ к фильму не подтверждён.\\n- [Архив журнала «Лёгкая атлетика» — ВФЛА](https://rusathletics.info/news/2405-oczifrovan-arxiv-zhurnala-legkaya-atletika/): найден первичный указатель архивов. PDF номера 1965 №11 не удалось надёжно получить; не выдаётся за прочитанную советскую методику.\\n- [Гостелерадиофонд: «Валерий Борзов», ТО «Экран», 1978](https://ok.ru/video/878633947540): просмотрена выборка из 12 кадров, в том числе изображение анализа движения. Полный фильм со звуком не просмотрен; страница копии не является официальным каналом архива.\\n- [«10 секунд Борзова» — копия на сайте федерации Узбекистана](https://uzathletics.uz/f/10_sekund_borzova.pdf): прочитаны выбранные страницы о задачах спринта и работе с Петровским, не все 62 страницы; выводы — в исследовательской записке. Это исторический рассказ участника, а не современный сравнительный эксперимент.\\n\\n## Реестр визуальных референсов\\n\\nДля видео «выбранные кадры» означает именно выборку, а не просмотр целиком со звуком. Это не позволяет проверять всю последовательность быстрых шагов. Скриншот не превращает тренерскую команду в научный норматив. A/B/C исключены из анализа ваших стартов. Даты относятся к материалам/метаданным, а не к дате ваших тренировок.\\n\\n| Материал | Ссылка | Статус визуальной проверки | Роль |\\n| --- | --- | --- | --- |\\n| Noah Lyles: starts, drills, gym | [Видео](https://www.youtube.com/watch?v=lPLH7OGMP9M) | Выбранные обзорные кадры; быстрая последовательность выхода требует отдельного уплотнения | Реальный элитный контекст, не цель копирования углов |\\n| Noah Lyles: A/B/C | [Видео](https://www.youtube.com/watch?v=xiYTMBLqp8c) | Выбранные обзорные кадры просмотрены | Разминка, исключена из оценки старта |\\n| Wall March | [Видео](https://www.youtube.com/watch?v=G1WvfCbg8uE) | Выбранные кадры просмотрены | Корпус и движение бедра |\\n| Falling Start | [Видео](https://www.youtube.com/watch?v=Rd3Bl2yAydY) | Выбранные кадры просмотрены | Переход от наклона к первому шагу |\\n| Push-Up Start | [Видео](https://www.youtube.com/watch?v=Wgrmhx6EIE4) | Выбранные кадры просмотрены | Организация выхода с пола |\\n| 3-Point Start | [Видео](https://www.youtube.com/watch?v=dgewJyq8ZFc) | Выбранные кадры просмотрены | Демонстрация; указанные 40–50° и 90° являются командами автора, не универсальными диапазонами |\\n| 3-point и ускорение | [Видео](https://www.youtube.com/watch?v=AYLad378i30) | Выбранные кадры просмотрены; реальный темп экспорта неизвестен | Поза меняется в ходе разгона |\\n| Landow / NSCA | [Видео](https://www.youtube.com/watch?v=uwDEyE6phDc) | Выбранные обзорные кадры просмотрены | Переход от подводящих упражнений к ускорению |\\n| Paris 2024: Alfred | [Olympics](https://www.youtube.com/watch?v=PrYvKzw9a78) | Выбранные обзорные кадры просмотрены | Соревнование элиты, не индивидуальный drill |\\n| Paris 2024: Alfred, другой монтаж | [Olympics](https://www.youtube.com/watch?v=6QGIgvMYD-A) | Выбранные обзорные кадры просмотрены | Второй монтаж того же забега; не независимое исследование |\\n\\nДополнительно визуально проверены кадры четырёх публичных материалов самого ALTIS World (метаданные канала проверены):\\n\\n| Материал | Ссылка | Статус / применение |\\n| --- | --- | --- |\\n| Stuart McMillan: The Keys to Late Acceleration, Part 2 | [ALTIS](https://www.youtube.com/watch?v=8JPMqUfubK4) | 12 выбранных кадров; поздняя фаза отличается от первых опор. Не копируем её углы в старт |\\n| Drop-in Accelerations | [ALTIS](https://www.youtube.com/watch?v=L_Nx_yfKumQ) | 12 выбранных кадров; ускорение из движения. Не добавляем вместо обучения старту из покоя |\\n| Block Clearance Mailboxes | [ALTIS](https://www.youtube.com/watch?v=ESaTlDKp_wc) | 12 выбранных кадров повторных выходов; разнообразие индивидуальных поз. Не назначаем положение элиты как норму |\\n| Block Starts and Block Set Up | [ALTIS](https://www.youtube.com/watch?v=eofiBE6aJzE) | 12 выбранных кадров настройки и выхода. Освоение педалей остаётся отдельной практикой |\\n\\n## Запросы и границы поиска\\n\\nИскались: sprint start biomechanics review; block start joint kinetics; acceleration transition kinematics; wall drill transfer; external attentional focus sprint; challenge point motor learning; resisted sprint meta-analysis; российская техника низкого старта; советские учебные фильмы и Борзов; публичные SKILL.md для pose analysis, sprint/running coach, scientific literature review, critical thinking, sports experiments, Socratic learning и Albert Safin beliefs. Использованы PubMed/Europe PMC, сайты издателей, НГУ Лесгафта, федерации, NSCA, авторские видео, NetFilm и исходные GitHub-репозитории. Полные чужие статьи и субтитры в отслеживаемой части репозитория не сохранены.\\n\\nНе найдено достаточного прямого основания для: единственного диапазона углов Wall drill; превосходства Push-Up над 3-point у новичков; автоматического исправления плохой техники повторениями; точных дозировок именно этим двум людям. Не найдено не означает, что таких данных не существует.\\n\\nФактически визуально проверены выборки из **15 видео**: десять строк первой таблицы, фильм о Борзове и четыре материала ALTIS. Это не 15 просмотренных целиком тренировок: два монтажа Парижа показывают один забег, фильм содержит другие эпизоды, A/B/C остаётся разминкой. После исключения двух олимпийских монтажей и A/B/C остаются 12 материалов о тренировках/старте, включая исторический фильм. Проверены выбранные кадры, а не полный звук и каждое движение всех роликов. Советский фильм визуально проверен один; просмотр 10–20 советских фильмов не выполнен.\\n\\n## Дополнение 5 октября: форма спины и отдельные измерения\\n\\nЭто две дополнительные научные работы к исходному реестру из 21; обе проверены на уровне аннотаций, не полных методов. Не считать новый поиск систематическим обзором.\\n\\n| Источник | Проверено | Применимость и ограничение |\\n| --- | --- | --- |\\n| [The geometric curvature of the spine of runners during maximal incremental effort test, 2015](https://pubmed.ncbi.nlm.nih.gov/25770754/) | Аннотация, 13 любителей, стереофотограмметрия при беге на дорожке | Индивидуальная форма; наклон туловища не является измерением кривизны. Нет норм Wall или доказательства влияния исправления на старт |\\n| [Speed-dependent increase in lumbar lordosis…, 2025](https://pubmed.ncbi.nlm.nih.gov/40288298/) | Аннотация и [сообщение авторского университета](https://www.arihhp.taiiku.tsukuba.ac.jp/news_en/20250508/); 18 мужчин-спортсменов, маркеры T12–L5, дорожка | Различие прямого измерения кривизны и косвенных показателей таза/единого сегмента. Есть [corrigendum](https://pubmed.ncbi.nlm.nih.gov/40450493/), текст не проверен; PDF вернул 429. Численные результаты не используются как норматив |\\n\\n[Как применены эти ограничения](back-and-trunk.md). Для текущих спортсменов точные углы позвоночника и влияние на время остаются неизвестными.\\n","research":"# Что исследование меняет в нашей работе\\n\\nПроверено 4 октября 2026 года. [Реестр источников и статусы чтения](start-sources.md), [обучение упражнениям](technique-learning.md), [проверка предположений](assumptions.md).\\n\\n## Основные решения\\n\\n**Повторять с ошибками можно, но ошибка должна быть частью управляемой попытки, а не целью.** Не требуется идеальная поза перед первым занятием. Требуется понятная задача, возможность заметить отклонение и изменить следующий повтор. Теория сложности обучения поддерживает подбор задачи по уровню, а не правило «делай как угодно — мышцы всё исправят». [Guadagnoli & Lee](https://doi.org/10.3200/jmbr.36.2.212-224).\\n\\n**Медленнее — полезно для контроля, но недостаточно для быстрых действий.** Для Wall March можно снизить темп и амплитуду. Для Single Switch надо в итоге сохранить быструю смену, упростив число смен. Для настоящего старта важны динамические условия. Это практический вывод из различия задач и принципа специфичности, а не результат прямого эксперимента с вашими упражнениями. [Haugen et al.](https://doi.org/10.1186/s40798-019-0221-0).\\n\\n**Общие задачи важнее копирования элиты.** Нужны продвижение вперёд, согласованная смена опоры и постепенное изменение положения тела. Поза в колодках, Wall drill и контакт третьего шага решают разные задачи. По одному кадру нельзя вывести направление силы, истинный центр массы или недостаток силы конкретной мышцы. [Morin et al.](https://doi.org/10.1249/mss.0b013e318216ea37), [координация первых шагов](https://doi.org/10.1242/bio.059501).\\n\\n**Рост силы и улучшение техники не одно и то же.** Силовые занятия могут улучшать спринт, но не подтверждают, что исчезнет конкретная ошибка постановки стопы. [Seitz et al.](https://doi.org/10.1007/s40279-014-0227-1).\\n\\n**Успех упражнения и перенос в разгон проверяются отдельно.** Для Wall drills и сравнения Push-Up/3-point у этих двух новичков прямого убедительного подтверждения превосходства одного метода в найденных источниках нет. Они остаются тренерскими инструментами. Снимать настоящий старт после упражнения и на следующем занятии без подсказки — наше решение для проверки, не обещание эффекта. [Landow / NSCA](https://www.nsca.com/education/videos/bridge-series/the-bridge-coaching-acceleration/).\\n\\n## Какие углы можно сравнивать\\n\\n| Параметр | Что поддерживают источники | Что нельзя назначать |\\n| --- | --- | --- |\\n| Наклон Wall drill | Контроль линии корпуса при выбранном наклоне — тренерская задача. Проверенного универсального диапазона для наших новичков не найдено | «Всем ровно 45°» |\\n| Колени в положении готовности в колодках | Есть описательные значения разных групп, различия настройки, антропометрии и способов измерения; оптимум по одному углу не установлен | Считать одно значение обязательным и переносить его на Wall Hold |\\n| Колено в конце первой беговой опоры после колодок | В обзоре описывается максимальное разгибание примерно 160–170° в соответствующих исследованиях | Требовать всем 180° и намеренно задерживать отрыв стопы |\\n| Стопа относительно центра массы | Положение меняется по мере разгона; первые опоры и более поздние отличаются | «На всех шагах стопа обязана быть сзади таза» |\\n| Высота бедра и угол поднятого колена | Они зависят от фазы, наклона, темпа и цели упражнения | Проверять только горизонталь бедра или ровно 90° в колене |\\n\\nОснование для строк о колодках и первой опоре — [Bezodis et al.](https://doi.org/10.1007/s40279-019-01138-1), для изменения положения стопы — [Nagahara et al.](https://doi.org/10.1242/bio.20148284). Числа из исследования не являются нормой для конкретного человека. Наши углы на кадрах — отдельные оценки проекции с неизвестной систематической ошибкой перспективы.\\n\\n## Российские и советские материалы\\n\\nВ [схеме Wall1 Landow](https://coachathletics.com.au/coaching-education/three-great-acceleration-drills-loren-landows-drill-progression) поднятое бедро направлено примерно перпендикулярно наклонной линии тела. Поэтому «бедро горизонтально» при наклонном корпусе не воспроизводит именно эту модель: колено может быть слишком близко к животу. Для выбранного Wall-упражнения пробуем меньший подъём, но не назначаем ровно 90° всем и не переносим эту позу на каждый беговой шаг. Угол зависит от длины сегментов, наклона, задачи и доступного контроля; более сильный или быстрый спортсмен может выполнять иные динамические положения. Силу по нашему кадру не измерить.\\n\\nВ российской работе Тютикова и Войновой есть полезный фокус на первых трёх шагах, но эксперимент с двумя КМС и табличная неясность недостаточны для общего назначения углов. [Сборник Лесгафта, с. 487–490](https://lesgaft.spb.ru/sites/default/files/u1/upload/m2.pdf).\\n\\nВ выбранных главах Борзов описывает разложение результата на отдельные задачи и плавный выход из стартового наклона, а также пересмотр тренером собственной программы после неудачного периода. Берём принцип проверять конкретную задачу и свои решения. Не берём его личную программу, показатели и историю как доказательство лучшего метода для новичков. Прочитаны выбранные страницы, не вся книга. [«10 секунд — целая жизнь»](https://uzathletics.uz/f/10_sekund_borzova.pdf).\\n\\nВ фильме «Валерий Борзов» 1978 года просмотрена выборка кадров, включая изображение анализа бегового движения; полный фильм со звуком не просмотрен. [Копия фильма](https://ok.ru/video/878633947540). Архивные описания NetFilm сохранены как указатели, не как просмотренные тренировки. Возраст материала и статус чемпиона не заменяют оценку применимости.\\n\\nВ диафильме Рохлина [«Бег на короткие дистанции», 1971](https://www.allforchildren.ru/diafilm/diafilm419.php) прочитаны подписи 41 кадра и визуально проверены 14 выбранных изображений, включая подготовку и выход. Полезна последовательность «готовность → выход → постепенный подъём». Упоминания полного разгибания и длины шагов не назначаем буквально: это учебная модель другой эпохи, не индивидуальный норматив и не контролируемое исследование.\\n\\n## Следующая исследовательская проверка\\n\\nПолучить сопоставимые первые пять контактов и реальную шкалу времени; сравнить один вариант старта с одной командой; повторить без команды на следующем занятии. Санки, сопротивление партнёра, дополнительные прыжковые блоки и длинные серии реакции пока не добавлять без подтверждённой задачи. Метаанализы сопротивления дают неоднородные результаты относительно обычного спринта; новый инструмент не обязательное решение. [Aldrich et al.](https://doi.org/10.70252/vkav1115), [обзор 2024 года](https://doi.org/10.1186/s40798-024-00777-7).\\n","pipeline":"# Порядок анализа стартов без колодок\\n\\nВерсия 1, 4 октября 2026 года. [Текущий разбор](../reviews/2026-10-04-starts.md), [источники](start-sources.md), [проверка готовых навыков](skill-audit.md).\\n\\n## Вход и сохранение\\n\\nПринимать указанную папку, уточнить людей, дату занятия и замедление. Уже известно: Рамир в красном, Миша с белыми волосами. Не брать дату загрузки за дату тренировки. Оригиналы не изменять. Оригиналы и служебные сетевые manifest остаются в исключённой из Git `media/`. Позднейшее разрешение пользователя 4 октября распространяется на публичные отчёты и выбранные собственные производные в существующем athletics-reviews: хранить их в `reviews/assets/` и публиковать без повторного вопроса о том же способе доступа. Оно не разрешает распространять чужие оригиналы.\\n\\nПредпочтительный способ — выбранные кадры через ограниченные HTTP Range, без сохранения целого ролика. При этом байты видео всё равно передаются и декодируются: это не просмотр «без скачивания вообще». Скрипт [stream_frames.py](../scripts/stream_frames.py) отказывается читать полный ответ, если сервер не соблюдает Range. При отказе сервера не переходить молча на полную загрузку. Manifest хранит источник, размер, PTS, поворот, хеш выбранного кадра и сетевой объём; хеш исходного ролика неизвестен, если он целиком не прочитан.\\n\\n## Два прохода\\n\\n1. Обзор: найти упражнения, отдельные попытки, пригодные ракурсы и перекрытия. Редкие обзорные кадры не позволяют нумеровать первые шаги.\\n2. Непрерывный короткий участок каждой выбранной попытки: исходная поза → начало движения → первый контакт → отрыв → следующие контакты. При необходимости уплотнить выборку до соседних кадров исходника. Даже 10 кадров на секунду файла может пропустить контакт при реальной скорости; этот темп не является достаточным по умолчанию.\\n\\nДля Wall drill различать удержание, медленный подъём, быструю одиночную смену с фиксацией и серию быстрых смен. Не судить удержание по переходному кадру. Для Reaction Start нужны доступный сигнал и последовательность движения; обычный старт не доказывает реакцию по случайному звуку.\\n\\n## Разметка и углы\\n\\nРучные точки проверять на исходном разрешении. Связать каждый кадр с участником, ногой, фазой и файлом. Не отражать картинку для сравнения, не менять сторону ноги. При перекрытии сустава оставить угол неизвестным. Разметка средствами геометрии/Pillow сохраняет реальные пиксели; генеративные изображения для измерений не подходят.\\n\\nДля каждого угла указывать точки и определение: плечо–таз к горизонтали изображения; таз–колено–голеностоп — внутренний угол колена; плечо–таз–колено — геометрический угол бедра к корпусу, который не равен клинической оценке тазобедренного сгибания. Опорная стопа на носке не означает, что голеностоп и точка контакта совпадают. Линия плечо–голеностоп проверяет общий силуэт, а не положение всех позвонков.\\n\\nОкруглять пользовательские оценки до целых градусов и отмечать неопределённость. Смещение выбранных точек на несколько пикселей показывает чувствительность расчёта, но не исправляет перспективу и не является доверительным интервалом. При косом ракурсе цифры остаются углами проекции. Горизонталь изображения не гарантирует горизонталь дорожки; отдельный кадр не измеряет прогиб поясницы, направление силы или истинный центр массы.\\n\\n## Вывод и перенос\\n\\nНаблюдение → возможное влияние → одна пробная команда → повторная попытка → проверка настоящего ускорения. Сначала механика, затем длина шагов. Сантиметры требуют масштаба в плоскости бега; время и частота — известной временной шкалы. Таз можно использовать как ориентир перемещения, но не называть истинным центром массы.\\n\\nПроверка переноса: 2–3 сопоставимые попытки без команды, затем с одной командой, затем без неё на следующем занятии. Сохранять все попытки, условия, ошибку хронометража и восстановление. Для 5/10/20/30 м нужны фиксированные дистанции, одинаковое начало отсчёта и предпочтительно электронные ворота; ручное время не позволяет уверенно судить о малых улучшениях. Не превращать один удачный повтор в доказательство эффективности.\\n\\nИтог оформлять по [14 разделам](../templates/start-review.md), отдельно для людей. Если контакты не видны, прямо отметить границу разбора и дать способ переснять. После появления колодок провести отдельную проверку: старт без педалей не воспроизводит всю их механику.\\n","plan":"# Пробное занятие: старт и первые контакты\\n\\nПодготовлено 4 октября 2026 года. Дата выполнения не назначена. Это будущий вариант, а не запись выполненного занятия. Основание: [новый разбор](../reviews/2026-10-04-starts.md), [научные ограничения](../docs/start-research.md).\\n\\n**Одна задача: сохранить организованный выход вперёд и проверить перенос работы у стены в настоящий разгон.** Из десяти стартовых вариантов оставляем пять упражнений. Это учебная доза, выбранная для проверки, а не установленный исследованиями оптимум.\\n\\nПеред выполнением каждый отдельно проверяет восстановление после зала/футбола/шиповок за 48–72 часа, сон и текущее состояние ног. Прежнее «болей нет» не подтверждает сегодняшнее состояние. При локальной боли, хромоте или нарастающем натяжении быстрый блок не выполнять; не устраивать предельный старт для проверки. Подробные условия очной оценки — в [основном отчёте](../docs/report.md).\\n\\n## Подготовка\\n\\nПривычная разминка из действующего плана, без трёх длинных самостоятельных блоков A/B/C. Их техника в этом документе не оценивается. Подводящие ускорения: **3 × 20 м**, в кроссовках, постепенно от свободного бега к быстрому контролируемому, отдых **60–90 с**. Это **60 м** отдельно от основных стартов; возвращение и торможение не включены в это число. Нужен свободный участок после конца отрезка для плавного снижения скорости.\\n\\n## Основные упражнения\\n\\n| Упражнение | Пробная доза | Отдых | Зачем / команда | Обувь и усилие |\\n| --- | --- | --- | --- | --- |\\n| Wall Hold | 2 удержания по 8 с с каждой поднятой ногой: 4 удержания, 32 с всего | 20–30 с между удержаниями | Сохранить пригодную линию в менее сжатой позе: «колено вперёд, не к животу»; остановить подъём раньше без изменения пояса | Кроссовки, устойчивое положение без предельного наклона |\\n| Wall March | 2 подхода по 3 подъёма каждой ногой: 6 подъёмов за подход, 12 всего; фиксация 1–2 с сверху | 45–60 с между подходами | Удержать линию при подъёме и вернуть стопу без перестановки корпуса | Кроссовки, медленно, без погони за высотой колена |\\n| Wall Single Switch | 2 подхода по 2 смены с каждой исходной поднятой ногой: 4 смены за подход, 8 всего | 10–15 с для нового исходного положения; 60 с между подходами | Прямая смена опоры вместо подъёма через длительную остановку на двух стопах: «сменил — замри» | Кроссовки; сама смена быстрая, число смен малое |\\n| Falling Start | 2 × 10 м каждому | 2 мин между попытками | Проверить перенос цельного наклона: «падай целиком, уходи вперёд» | Кроссовки; быстрый организованный выход без попытки рекорда |\\n| 3-Point Start | Рамир: 3 × 10 м + до 2 × 20 м. Миша: 3 × 10 м + до 1 × 20 м | 2–3 мин для 10 м, 3–4 мин для 20 м; больше при неполном восстановлении | Рамиру проверить немного более высокий таз до попытки: «из стойки уходи вперёд». Мише: «толкни дорожку назад — унеси тело вперёд». На повторение одна команда | Шиповки только при привычном безболезненном использовании и нормальном восстановлении; быстрый решительный выход, без предельной попытки |\\n\\nРазная верхняя доза 3-point — консервативное решение для первой проверки: по Мише меньше индивидуальных данных о нагрузке и восстановлении. Это не вывод, что он слабее, и не назначение результата Рамира Мише. Если готовность не подтверждена, оба начинают с 3 × 10 м; удлинения являются верхней границей, а не обязательством закончить таблицу.\\n\\nЕсли не удаётся быстрая одиночная смена у стены, сделать **только один подход** Single Switch и вернуться к March; не добивать восемь неуправляемых повторов. Если после отдыха целевая механика в стартах не возвращается, закончить быстрый блок раньше. Разовая неудача не повод отменять всё упражнение; устойчивое ухудшение не повод добавлять ещё попытки.\\n\\n## Метры отдельно\\n\\nТаблица показывает верхний вариант, когда выполнены все разрешённые удлинения. Без них 3-point составляет 30 м у каждого, основные ускорения 50 м, с подводящими 110 м; в шиповках до 30 м при указанной обуви. Факт записывать по выполненным повторам.\\n\\n| Участник | Подводящие | Falling | 3-point | Основные ускорения | В шиповках при указанной обуви |\\n| --- | --- | --- | --- | --- | --- |\\n| Рамир | 60 м | 20 м | 70 м | 90 м | 70 м |\\n| Миша | 60 м | 20 м | 50 м | 70 м | 50 м |\\n\\nВсего ускорений с подготовкой: **150 м** у Рамира и **130 м** у Миши. Статические удержания, подъёмы у стены, СБУ и ходьба не превращаются в спринтерские метры. Если основной блок выполняется в кроссовках, метры в шиповках равны нулю. Три часа доступного манежа не нужно заполнять тремя часами быстрых стартов.\\n\\n## Что заменяет этот вариант\\n\\nОн заменяет подводящие ускорения и стартовую основную часть [прежнего ближайшего занятия](first-session.md): вместо прежних 3 × 30 м подводящих выполнить указанные здесь 3 × 20 м; вместо 4 × 20 м + 2 × 40 м — новую основную таблицу. Не прибавлять прежние 90 м и 160 м поверх нового объёма. [12 недель](12-weeks.md) остаются исторической структурой, календарный номер недели не разрешает автоматическое увеличение. Отдельных прыжковых блоков не добавляем по последнему ограничению пользователя.\\n\\nPush-Up Start в просмотренных попытках не показал преимущества для следующего обычного ускорения; часть его опор перекрыта. Поэтому он, 4-point без колодок и Reaction Start в эту проверку не включены. Для отдельного сравнения Push-Up заменить им один из назначенных 10-метровых повторов 3-point; не добавлять серию сверху. При появлении колодок заменить часть 3-point знакомством с педалями и повторным видеоразбором, а не добавлять ещё одну полную серию.\\n\\n## Проверка результата\\n\\nСнять первую попытку без новой команды и следующие с одной командой; сохранить также неудачные. На следующем занятии повторить без напоминания. Пока неизвестно замедление и нет разметки дистанции, оценивать видимое действие, а не обещать выигрыш сотых. Проверку 30 м назначить после подтверждения первых контактов; этот короткий план сам по себе ещё не проверяет разгон до 30 м.\\n"}'),o={"mobile/red-wall.png":[820,810],"annotations/red-wall.png":[1e3,1210],"mobile/white-wall.png":[660,680],"annotations/white-wall.png":[1e3,1052],"back-axis.svg":[540,650],"wall-target.svg":[540,390],"red-wall-two-feet.jpg":[470,430],"red-wall-motion.gif":[470,430],"white-wall-two-feet.jpg":[470,430],"white-wall-motion.gif":[470,430],"march-target.svg":[540,390],"switch-target.svg":[540,390],"mobile/red-contact-1.png":[520,480],"annotations/red-contact-1.png":[1e3,684],"falling-target.svg":[540,390],"mobile/red-low-contact-2.png":[620,580],"annotations/red-low-contact-2.png":[1e3,756],"mobile/red-contact-2.png":[540,480],"annotations/red-contact-2.png":[1e3,684],"forward-target.svg":[540,410],"mobile/white-contact-2.png":[560,460],"annotations/white-contact-2.png":[1e3,664],"red-pushup-crop.png":[185,134],"white-pushup-crop.png":[260,145],"white-ready-crop.png":[270,205]},c={people:e,cards:n,skills:i,map:t,tasks:a,assumptions:s,documents:r,dimensions:o};export{c as d};
